/* ============================================================
   STUTI — the thirteen Pūrṇimās, and the Satyanārāyaṇa vratakathā
   Each lunar month carries a full moon, and most carry a story the
   elders tell on that day — Hanumān on Caitra, Vyāsa on Āṣāḍha,
   Hayagrīva on Śrāvaṇa, the burning of the three cities on Kārtika.
   Some of these accounts name the full moon themselves; others are
   festival associations the tradition later set upon the day. The
   collection says which is which, and does not invent a tithi where
   the text gives none.

   This file holds, for each month's pūrṇimā, the name, the day it is
   kept by, the introduction that frames the account, the story, the
   full-moon connection, the source, and the keeping. The intercalary
   month carries its own, Adhika-māsa Pūrṇimā. At the end stands the
   Satyanārāyaṇa vratakathā in its five chapters — the katha read on
   any pūrṇimā a household keeps.

   The stories are accessible retellings of the Purāṇas and the two
   Itihāsas, not verse-by-verse translations. Attribution and detail
   vary between editions; a family's own elders outrank this app.
   ============================================================ */
window.STUTI_PURNIMA = (function () {
  const P = () => window.AKSHARA_PANCHANGA;
  const MASA = { caitra: 0, vaisakha: 1, jyeshtha: 2, ashadha: 3, shravana: 4, bhadrapada: 5,
                 ashvina: 6, kartika: 7, margashirsha: 8, pausha: 9, magha: 10, phalguna: 11 };

  /* ---------- the thirteen ----------
     key: { masa } for the regular year; { adhika: true } for the
     intercalary month. differs: true where a keeping is written in
     `niyama`. Every full moon is the śukla pūrṇimā, so there is no
     fortnight to fix — only the month. */
  const LIST = [{"id":"chaitra-purnima","key":{"masa":0},"name":{"roman":"Caitra Pūrṇimā","deva":"चैत्र पूर्णिमा","tel":"చైత్ర పౌర్ణమి"},"when":{"roman":"Hanumān Jayantī, in some regions","deva":"हनुमान् जयन्ती — कुछ क्षेत्रों में","tel":"హనుమాన్ జయంతి — కొన్ని ప్రాంతాల్లో"},"source":{"roman":"Vālmīki Rāmāyaṇa, Kiṣkindhā-kāṇḍa 66","deva":"वाल्मीकि रामायण, किष्किन्धा-काण्ड ६६","tel":"వాల్మీకి రామాయణం, కిష్కింధకాండ 66"},"meaning":{"roman":"The vanaras searching for Sita have reached the seashore. They are discouraged by the question of who can cross the ocean to Lanka. Hanuman remains silent. Jambavan reminds him of his strength, intelligence and courage, asking why he does not put his abilities to use. He then recounts Hanuman's birth. This is an encouragement before a mission, rather than a dialogue prescribing a full-moon vow.","deva":"सीता की खोज में निकले वानर समुद्रतट पर पहुँचे। लंका तक समुद्र कौन पार कर सकता है, इस चिन्ता से सेना निराश थी। हनुमान मौन थे। जाम्बवान ने उनके बल, बुद्धि और पराक्रम का स्मरण कराया। “तुम अपनी शक्ति का उपयोग क्यों नहीं करते?” कहकर उन्होंने हनुमान का जन्मवृत्तान्त सुनाया। यह पूर्णिमा-व्रत की विधि पूछने का संवाद नहीं, कार्यसाधन के लिए प्रोत्साहन का प्रसंग है।","tel":"సీతను వెతుకుతున్న వానరులు సముద్రతీరానికి చేరారు. లంకకు చేరేందుకు సముద్రాన్ని దాటగలవారు ఎవరనే ప్రశ్నతో సేన నిరుత్సాహపడింది. హనుమంతుడు మౌనంగా ఉండగా జాంబవంతుడు అతని బలం, బుద్ధి, పరాక్రమాన్ని గుర్తుచేశాడు. “నీ శక్తిని ఎందుకు ఉపయోగించుకోవడం లేదు?” అని అడిగి అతని జన్మవృత్తాంతాన్ని చెప్పాడు. ఇది పౌర్ణమి వ్రతవిధిని అడిగిన సంభాషణ కాదు; కార్యసాధనకు ప్రోత్సహించే సందర్భం."},"story":{"roman":"The celestial woman Punjikasthala was born as a vanara woman under a curse and became known as Anjana. She was Kunjara's daughter and Kesari's wife, able to assume forms at will. One day she walked on a mountain in human form. Disturbed by Vayu's unseen touch, she feared that her fidelity had been violated. Vayu reassured her: through his mental agency she would bear a courageous, intelligent son, equal to him in leaping and movement. Anjana gave birth to Hanuman in a cave.\n\nAs a child, Hanuman mistook the rising sun for a fruit and flew towards it. Indra struck him with his thunderbolt. He fell on a mountain and injured his jaw; Jambavan connects this injury with his name, Hanuman. In grief Vayu stopped blowing. When the worlds became distressed, the gods bestowed boons upon the child. Brahma protected him from death by weapons, and Indra granted that his death would occur only at his own choosing.\n\nJambavan concluded that Hanuman was Kesari's son and Vayu's son, and urged him to display his courage and cross the ocean. Inspired, Hanuman enlarged his form and prepared for the task.","deva":"पुञ्जिकस्थला नाम की अप्सरा शाप के कारण वानरी बनी और अञ्जना कहलायी। वह कुञ्जर की पुत्री तथा केसरी की पत्नी थी और इच्छानुसार रूप धारण कर सकती थी। एक दिन वह मनुष्यरूप में पर्वत पर घूम रही थी। वायु के अदृश्य स्पर्श से घबराकर उसे अपने पातिव्रत्य के भंग होने का भय हुआ। वायु ने आश्वस्त किया कि उनके मानसिक अनुग्रह से उसे बलवान और बुद्धिमान पुत्र होगा, जो छलाँग और गति में उनके समान होगा। अञ्जना ने एक गुफा में हनुमान को जन्म दिया।\n\nबालक हनुमान ने उगते सूर्य को फल समझकर उसकी ओर उड़ान भरी। इन्द्र ने वज्र मारा। पर्वत पर गिरने से उनका हनु अर्थात् जबड़ा चोटिल हुआ; जाम्बवान इससे हनुमान नाम का सम्बन्ध बताते हैं। दुःखी वायु ने बहना बन्द कर दिया। लोकों के व्याकुल होने पर देवताओं ने बालक को वर दिए। ब्रह्मा ने शस्त्रों से मृत्यु न होने और इन्द्र ने इच्छानुसार ही मृत्यु होने का वर दिया।\n\nजाम्बवान ने कहा कि वे केसरी और वायु के पुत्र हैं; अब पराक्रम दिखाकर समुद्र पार करें। प्रेरित हनुमान ने अपना रूप बढ़ाया और कार्य के लिए तैयार हुए।","tel":"పుంజికస్థల అనే అప్సరస శాపం వల్ల వానరస్త్రీగా జన్మించి అంజనగా ప్రసిద్ధి చెందింది. ఆమె కుంజరుని కుమార్తె, కేసరి భార్య. కావలసిన రూపాన్ని ధరించగల ఆమె ఒకరోజు మానవరూపంలో పర్వతంపై సంచరించింది. వాయుదేవుని అదృశ్యస్పర్శతో కలవరపడిన ఆమె తన పాతివ్రత్యానికి భంగం కలుగుతుందేమోనని భయపడింది. వాయువు భయపడవద్దని చెప్పి, తన మానసిక అనుగ్రహంతో ఆమెకు బలం, బుద్ధి కలిగిన కుమారుడు జన్మిస్తాడని తెలిపాడు. దూకడంలో, ప్రయాణంలో తనతో సమానుడవుతాడని చెప్పాడు. అంజన గుహలో హనుమంతుణ్ని ప్రసవించింది.\n\nబాలుడైన హనుమంతుడు ఉదయించే సూర్యుణ్ని పండుగా భావించి ఆకాశంలోకి ఎగిరాడు. ఇంద్రుని వజ్రం తగిలి పర్వతంపై పడగా అతని దవడ దెబ్బతింది; అందువల్ల హనుమాన్ అనే పేరు వచ్చిందని జాంబవంతుడు వివరించాడు. వాయువు దుఃఖంతో వీచడం ఆపాడు. లోకాలు కలత చెందగా దేవతలు బాలునికి వరాలు ప్రసాదించారు. బ్రహ్మ ఆయుధాల వల్ల చావు ఉండదని, ఇంద్రుడు తన ఇష్టానుసారమే మరణం సంభవిస్తుందని అనుగ్రహించారు.\n\n“నీవు కేసరి కుమారుడవు, వాయుపుత్రుడవు. ఇప్పుడు నీ పరాక్రమాన్ని చూపి సముద్రాన్ని దాటు” అని జాంబవంతుడు ముగించాడు. ఆ ప్రోత్సాహంతో హనుమంతుడు తన రూపాన్ని పెంచుకుని కార్యానికి సిద్ధమయ్యాడు."},"connection":{"roman":"Some regions celebrate Hanuman's birth on Chaitra Purnima; other regions follow different dates. This sarga does not state a birth tithi.","deva":"कुछ क्षेत्रों में हनुमज्जयन्ती चैत्र पूर्णिमा को होती है; अन्य क्षेत्रों में अलग तिथियाँ हैं। इस सर्ग में जन्मतिथि नहीं बताई गई है।\n\n<a id=\"purnima-02\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"కొన్ని ప్రాంతాల్లో హనుమజ్జయంతి చైత్ర పౌర్ణమినాడు జరుగుతుంది. ఇతర ప్రాంతాల్లో ఇతర తిథులు ఉన్నాయి. పై సర్గలో జన్మతిథి చెప్పబడలేదు."},"niyama":{"roman":"Where Hanuman Jayanti falls on Chaitra Purnima, worship Hanuman and pray for the world's welfare. Temples perform abhisheka and special decoration. Retain the Andhra tradition of Vaishakha Krishna Dashami where followed. The temple source checked gives no universal fasting, water-abstinence or fast-breaking rule.","deva":"चैत्र पूर्णिमा पर हनुमज्जयन्ती मानने वाली परम्परा में हनुमान की पूजा और विश्वकल्याण की प्रार्थना करें। मन्दिरों में अभिषेक और विशेष अलङ्कार होते हैं। आन्ध्र की वैशाख कृष्ण दशमी वाली परम्परा का दिन न बदलें। जाँचे गए मन्दिर-स्रोत में सबके लिए अनिवार्य उपवास, निर्जल-व्रत या पारण-समय नहीं बताया गया है।","tel":"హనుమజ్జయంతిని చైత్ర పౌర్ణమినాడు జరుపుకునే సంప్రదాయంలో హనుమంతుని పూజించి, లోకక్షేమం కోసం ప్రార్థించవచ్చు. దేవాలయాల్లో అభిషేకం, ప్రత్యేక అలంకారం జరుగుతాయి. ఆంధ్రప్రాంత వైశాఖ కృష్ణ దశమి జయంతి సంప్రదాయాన్ని దీనితో మార్చవద్దు. పరిశీలించిన దేవాలయ ఆధారంలో అందరికీ తప్పనిసరి ఉపవాసం, నిర్జలవ్రతం లేదా నిర్దిష్ట పారాణ సమయం చెప్పలేదు."},"differs":true},{"id":"vaisakha-purnima","key":{"masa":1},"name":{"roman":"Vaiśākha Pūrṇimā","deva":"वैशाख पूर्णिमा","tel":"వైశాఖ పౌర్ణమి"},"when":{"roman":"Vaiśākha snāna · Mādhava Pūrṇimā","deva":"वैशाख स्नान · माधव पूर्णिमा","tel":"వైశాఖ స్నానం · మాధవ పౌర్ణమి"},"source":{"roman":"Padma Purāṇa, Pātāla-khaṇḍa 98","deva":"पद्म पुराण, पाताल-खण्ड ९८","tel":"పద్మ పురాణం, పాతాళఖండం 98"},"meaning":{"roman":"Suta relates a dialogue between Dharmaraja and a brahmana. Having heard about bathing in Vaisakha, the brahmana asks Yama how one should worship Vishnu after the morning bath, and which flowers to offer. Dharmaraja explains tulasi worship, charity and the month's final three sacred days, then introduces Dhanasharman's account.","deva":"सूत धर्मराज और एक ब्राह्मण का संवाद सुनाते हैं। वैशाख-स्नान की महिमा सुनकर ब्राह्मण यम से पूछता है कि इस मास में प्रातः स्नान के बाद विष्णु की पूजा कैसे और किन फूलों से करनी चाहिए। धर्मराज तुलसीपूजा, दान तथा मास के अन्तिम तीन पवित्र दिनों का माहात्म्य बताकर धनशर्मा का वृत्तान्त कहते हैं।","tel":"సూతుడు ధర్మరాజు–బ్రాహ్మణుని సంభాషణను వివరిస్తున్నాడు. వైశాఖ స్నానమహిమను విన్న బ్రాహ్మణుడు యమధర్మరాజును, “ఈ మాసంలో ఉదయాన్నే స్నానం చేసినవాడు విష్ణువును ఎలా ఆరాధించాలి? ఏ పుష్పాలు సమర్పించాలి?” అని అడిగాడు. ధర్మరాజు తులసీపూజ, దానం, వైశాఖ చివరి మూడు పుణ్యదినాల మహిమను వివరించి ధనశర్మ వృత్తాంతాన్ని చెప్పాడు."},"story":{"roman":"Dhanasharman went into a forest to collect kusha grass. He saw three pretas suffering from hunger and thirst and fled in fear. When they pursued him, he addressed them compassionately and invoked Vishnu's name. Hearing it softened their minds. They explained the deeds that had led to their condition.\n\nThe first, formerly Sudasa, had become Kritaghna through ingratitude. The second, formerly King Harivira, had arrogantly disregarded his teacher and eaten without giving to others; he became Vidaivata. The third was a brahmana named Gautama. Although he had performed Vedic rites, pride had made him neglect his teacher's counsel and Vaisakha bathing, charity and Vishnu worship. He called his resulting condition Avaishakha.\n\nWhen Gautama asked that his son Dhanasharman be informed, Dhanasharman realised that this was his own father. Grieving, he asked how to free him. His father said that it was Vaisakha Purnima and instructed him to bathe in the Yamuna, worship, give food, sesame and water vessels, and dedicate the merit to all three. He would not depart alone while leaving his companions behind.\n\nDhanasharman carried out these acts and assigned the merit separately to each. All three ascended to heaven in a celestial vehicle. The narrative says that Dhanasharman later attained Brahma's realm. The full-moon date is explicitly part of this story.","deva":"धनशर्मा कुश लेने वन गया। भूख-प्यास से पीड़ित तीन प्रेत देखकर वह डरकर भागा। उनके पीछा करने पर उसने दयापूर्वक उनसे बात की और विष्णु का नाम लिया। नाम सुनकर उनके मन में करुणा उत्पन्न हुई। उन्होंने अपनी अवस्था के कारण बताए।\n\nपहला पहले सुदास था; कृतघ्नता से कृतघ्न नाम का प्रेत बना। दूसरा हरिवीर राजा था; अहंकार से गुरु की अवज्ञा और दूसरों को दिए बिना भोजन करने के कारण विदैवत बना। तीसरा गौतम नाम का ब्राह्मण था। वैदिक कर्म करने पर भी गर्व से गुरु का उपदेश और वैशाख-स्नान, दान तथा विष्णुपूजा छोड़ दी थी। इसलिए वह अवैशाख कहलाया।\n\nगौतम ने अपने पुत्र धनशर्मा को समाचार देने को कहा। तब धनशर्मा ने पहचान लिया कि सामने उसके पिता हैं। दुःखी होकर मुक्ति का उपाय पूछा। पिता ने बताया कि आज वैशाख पूर्णिमा है। यमुना में स्नान, पूजा और अन्न, तिल तथा जलकलशों का दान करके पुण्य तीनों को देने का निर्देश दिया। उन्होंने कहा कि वे अपने दोनों साथियों को छोड़कर अकेले मुक्ति नहीं चाहते।\n\nधनशर्मा ने ऐसा ही किया और प्रत्येक को अलग-अलग पुण्य अर्पित किया। तीनों दिव्य विमान से स्वर्ग गए। कथा के अनुसार धनशर्मा भी बाद में ब्रह्मलोक पहुँचा। इस कथा में पूर्णिमा की तिथि सीधे कही गई है।\n\n<a id=\"purnima-03\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक · అదనపు పురాణసూచన · Additional Purana reference · अतिरिक्त पुराण-सन्दर्भ","tel":"ధనశర్మ అనే బ్రాహ్మణుడు కుశలు సేకరించడానికి అడవికి వెళ్లాడు. అక్కడ ఆకలిదాహాలతో బాధపడుతున్న ముగ్గురు ప్రేతాలను చూసి భయంతో పరుగెత్తాడు. అవి వెంబడించగా వాటిని దయతో సంబోధించి విష్ణుని నామాన్ని పలికాడు. భగవన్నామం విని వాటి మనస్సుల్లో దయ కలిగింది. తమ స్థితికి కారణాలను చెప్పాయి.\n\nమొదటివాడు పూర్వం సుదాసుడు; కృతఘ్నత వల్ల కృతఘ్న అనే ప్రేతమయ్యాడు. రెండవవాడు హరివీరుడు అనే రాజు; అహంకారంతో గురువును అవమానించి, ఇతరులకు ఇవ్వకుండా తినేవాడు. అతడు విదైవత అనే ప్రేతమయ్యాడు. మూడవవాడు గౌతముడు అనే బ్రాహ్మణుడు. వైదికకర్మలు చేసినా గర్వంతో గురూపదేశాన్ని నిర్లక్ష్యం చేసి, వైశాఖ స్నానం, దానం, విష్ణుపూజ చేయలేదని తెలిపాడు. అందువల్ల అవైశాఖ అనే స్థితి పొందానన్నాడు.\n\nగౌతముడు తన కుమారుడు ధనశర్మకు విషయం చెప్పమని కోరగానే, ఎదుట ఉన్నవాడు తన తండ్రేనని ధనశర్మ గుర్తించాడు. దుఃఖంతో విముక్తిమార్గం అడిగాడు. ఆ రోజు వైశాఖ పౌర్ణమి అని తండ్రి చెప్పి, యమునాస్నానం, పూజ, అన్నం, నువ్వులు, జలకలశాల దానం చేసి పుణ్యాన్ని ముగ్గురికీ సమర్పించమన్నాడు. తాను ఒక్కడినే విముక్తుడై మిగిలిన ఇద్దరిని విడిచిపెట్టనని కూడా చెప్పాడు.\n\nధనశర్మ ఆ ప్రకారం చేశాడు. పుణ్యాన్ని విడివిడిగా సమర్పించగానే ముగ్గురూ దివ్యవిమానంలో స్వర్గానికి వెళ్లారు. ధనశర్మ కూడా తరువాత బ్రహ్మలోకాన్ని పొందాడని కథ చెబుతుంది. ఈ కథలో పౌర్ణమి తిథి ప్రత్యక్షంగా పేర్కొనబడింది."},"connection":{"roman":"","deva":"","tel":""},"niyama":{"roman":"The chapter emphasizes morning bathing, Madhava worship and gifts of food, sesame and water vessels according to one's means. It also describes bathing and charity on Trayodashi, Chaturdashi and Purnima. Perform ancestral rites through one's inherited procedure. This full-moon teaching does not establish a waterless fast or Ekadashi grain restriction.","deva":"अध्याय में प्रातःस्नान, माधव-पूजा और सामर्थ्यानुसार अन्न, तिल तथा जलकुम्भ-दान प्रमुख हैं। त्रयोदशी, चतुर्दशी और पूर्णिमा पर स्नान-दान भी बताए गए हैं। पितृकर्म अपने परम्परागत विधान से करें। इस पूर्णिमा-उपदेश को निर्जल उपवास या एकादशी के अन्न-निषेध का नियम न मानें।","tel":"ఉదయస్నానం, మాధవుని పూజ, శక్తిమేరకు అన్నం–నువ్వులు–జలకలశాల దానం ఈ అధ్యాయంలో ప్రధాన ఆచరణలు. త్రయోదశి, చతుర్దశి, పౌర్ణమి మూడు రోజులకూ స్నానదానాలు చెప్పబడ్డాయి. పితృకర్మలు తమ సంప్రదాయ విధితో చేయాలి. ఇక్కడి పౌర్ణమి ఉపదేశాన్ని నిర్జల ఉపవాసం లేదా ఏకాదశి ధాన్యనిషేధంగా చెప్పకూడదు."},"differs":true},{"id":"jyeshtha-purnima","key":{"masa":2},"name":{"roman":"Jyeṣṭha Pūrṇimā","deva":"ज्येष्ठ पूर्णिमा","tel":"జ్యేష్ఠ పౌర్ణమి"},"when":{"roman":"Vaṭa Sāvitrī, in some regions","deva":"वट सावित्री — कुछ क्षेत्रों में","tel":"వట సావిత్రి — కొన్ని ప్రాంతాల్లో"},"source":{"roman":"Mahābhārata, Vana Parva 277–283","deva":"महाभारत, वन पर्व २७७–२८३","tel":"మహాభారతం, వన పర్వం 277–283"},"meaning":{"roman":"During exile, Yudhishthira tells Markandeya that Draupadi's suffering troubles him more than his lost kingdom. She rescued the Pandavas in the gambling hall and later suffered abduction by Jayadratha. He asks whether the sage has seen or heard of another devoted wife like her. Markandeya tells Savitri's story.","deva":"वनवास में युधिष्ठिर मार्कण्डेय से कहते हैं कि राज्य खोने से अधिक द्रौपदी के दुःख उन्हें व्यथित करते हैं। उसने द्यूतसभा में पाण्डवों को बचाया; बाद में जयद्रथ ने उसका अपहरण किया। वे पूछते हैं कि क्या मुनि ने उसके समान पतिव्रता को देखा या सुना है। मार्कण्डेय सावित्री की कथा सुनाते हैं।","tel":"వనవాసంలో యుధిష్ఠిరుడు మార్కండేయుణ్ని తన రాజ్యనష్టం కంటే ద్రౌపది కష్టాలు ఎక్కువగా బాధిస్తున్నాయని చెబుతాడు. జూదసభలో ఆమె తమను రక్షించిందనీ, తరువాత జయద్రథుడు ఆమెను అపహరించాడనీ గుర్తుచేస్తాడు. “ద్రౌపది వంటి మహాభాగ్యవతి, పతివ్రతను ఎప్పుడైనా చూశారా, విన్నారా?” అని అడుగుతాడు. మార్కండేయుడు సావిత్రి కథ చెబుతాడు."},"story":{"roman":"King Ashvapati of Madra pleased the goddess Savitri through prolonged discipline. His daughter, born by her blessing, was named Savitri. When choosing a husband, she selected Satyavan, son of Dyumatsena, a king who had lost both his sight and kingdom and lived in the forest. Narada warned that Satyavan would die within a year. Savitri remained firm in her choice.\n\nServing her husband's parents, she kept the appointed day in mind. She undertook a three-day vow beforehand and accompanied Satyavan into the forest that day. While cutting wood, he developed a severe headache and lay with his head in her lap. Yama appeared and took his life, explaining that Satyavan's virtues warranted his coming personally.\n\nSavitri followed Yama, speaking thoughtfully about righteousness, good company, compassion and trust. Pleased, he granted Dyumatsena restored sight and kingship, sons to Ashvapati, and sons to Savitri and Satyavan. She respectfully pointed out that the last boon could not be fulfilled without her husband and asked for his life. Yama gladly released him.\n\nSatyavan awakened, and the couple returned to the hermitage. Dyumatsena regained sight and his kingdom. Markandeya concluded by reassuring Yudhishthira that Draupadi, like Savitri, would help rescue her family.","deva":"मद्रराज अश्वपति ने दीर्घ नियमपालन से सावित्रीदेवी को प्रसन्न किया। उनके वर से उत्पन्न पुत्री का नाम सावित्री रखा गया। पति चुनते समय उसने सत्यवान को चुना। उसके पिता द्युमत्सेन दृष्टि और राज्य खोकर वन में रहते थे। नारद ने बताया कि सत्यवान एक वर्ष में मर जाएगा, फिर भी सावित्री अपने निर्णय पर दृढ़ रही।\n\nसास-ससुर की सेवा करते हुए उसने नियत दिन का ध्यान रखा। पहले तीन दिन व्रत किया और उस दिन पति के साथ वन गई। लकड़ी काटते समय सत्यवान के सिर में तेज पीड़ा हुई और वह उसकी गोद में लेट गया। यम प्रकट होकर उसका प्राण ले गए। उन्होंने कहा कि सत्यवान के सद्गुणों के कारण वे स्वयं आए हैं।\n\nसावित्री यम के पीछे चली और धर्म, सत्संग, करुणा तथा विश्वास पर विवेकपूर्ण बातें कहीं। प्रसन्न यम ने द्युमत्सेन को दृष्टि और राज्य, अश्वपति को पुत्र तथा सावित्री-सत्यवान को पुत्र होने के वर दिए। सावित्री ने विनय से कहा कि पति के बिना अन्तिम वर पूरा नहीं होगा और सत्यवान का जीवन माँगा। यम ने प्रसन्न होकर उसे मुक्त किया।\n\nसत्यवान जागा और दोनों आश्रम लौटे। द्युमत्सेन को दृष्टि और राज्य वापस मिले। मार्कण्डेय ने युधिष्ठिर को आश्वासन दिया कि सावित्री के समान द्रौपदी भी अपने परिवार को बचाएगी।","tel":"మద్రరాజు అశ్వపతి దీర్ఘకాల నియమాచరణతో సావిత్రీదేవిని ప్రసన్నం చేసుకున్నాడు. ఆమె వరంతో జన్మించిన కుమార్తెకు సావిత్రి అని పేరు పెట్టాడు. వివాహానికి తగిన వయస్సులో ఆమె సత్యవంతుణ్ని ఎంచుకుంది. అతడు చూపు, రాజ్యం కోల్పోయిన ద్యుమత్సేనుని కుమారుడు; కుటుంబం అడవిలో నివసిస్తోంది. సత్యవంతుడు ఒక సంవత్సరంలో మరణిస్తాడని నారదుడు చెప్పినా సావిత్రి తన నిర్ణయాన్ని మార్చలేదు.\n\nఆమె అత్తమామలను సేవిస్తూ మరణదినాన్ని గుర్తుంచుకుంది. చివరి మూడు రోజులు నియమంతో వ్రతం చేసింది. నిర్ణీత రోజు భర్తతో అడవికి వెళ్లింది. కట్టెలు కోస్తున్న సత్యవంతునికి తలనొప్పి వచ్చి ఆమె ఒడిలో పడుకున్నాడు. యముడు ప్రత్యక్షమై అతని జీవాన్ని తీసుకున్నాడు. సత్యవంతుని సద్గుణాల వల్ల తానే వచ్చానని చెప్పాడు.\n\nసావిత్రి యముణ్ని అనుసరించి ధర్మం, సత్సంగం, కరుణ, విశ్వాసం గురించి వివేకంతో మాట్లాడింది. ప్రసన్నుడైన యముడు ద్యుమత్సేనునికి చూపు, రాజ్యం, అశ్వపతికి కుమారులు, సావిత్రి–సత్యవంతులకు కుమారులు అనే వరాలు ఇచ్చాడు. చివరి వరం భర్త లేకుండా నెరవేరదని ఆమె వినయంగా గుర్తుచేసి అతని ప్రాణాన్ని కోరింది. యముడు సంతోషంగా సత్యవంతుణ్ని విడుదల చేశాడు.\n\nఅతడు మేల్కొన్నాడు; దంపతులు ఆశ్రమానికి చేరారు. ద్యుమత్సేనునికి చూపు, రాజ్యం తిరిగి వచ్చాయి. ఈ వృత్తాంతంతో మార్కండేయుడు ద్రౌపది కూడా పాండవులను కాపాడుతుందని యుధిష్ఠిరుణ్ని ఓదార్చాడు."},"connection":{"roman":"This account underlies the regional Jyeshtha Purnima Savitri observance. The epic passage does not state the event's month or tithi, nor does it prescribe tying thread around a banyan tree.","deva":"यह कथा क्षेत्रीय ज्येष्ठ पूर्णिमा के सावित्री-व्रत का आधार है। महाभारत के इस प्रसंग में घटना का मास या तिथि और वटवृक्ष पर धागा बाँधने की विधि नहीं दी गई है।\n\n<a id=\"purnima-04\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक · అదనపు పురాణసూచన · Additional Purana reference · अतिरिक्त पुराण-सन्दर्भ","tel":"జ్యేష్ఠ పౌర్ణమి వటసావిత్రి ఆచారానికి ఈ కథ ఆధారం. కానీ కథలో సంఘటన జరిగిన మాసం–తిథి చెప్పబడలేదు; వటవృక్షానికి దారం కట్టే విధి కూడా ఈ ఘట్టంలో లేదు."},"niyama":{"roman":"This Savitri vrata prescribes three days of fasting from Trayodashi. For reduced capacity: an evening meal on Trayodashi, unsolicited food on Chaturdashi, and fasting on Purnima. Bathing, worship of Savitri with Brahma, vigil and hearing the story accompany it, followed by gifts and feeding. These rules belong to this vrata; retain distinct local Amavasya observances.","deva":"इस सावित्री-व्रत में त्रयोदशी से तीन दिन का उपवास है। असमर्थता में त्रयोदशी को नक्तभोजन, चतुर्दशी को अयाचितभोजन और पूर्णिमा को उपवास बताया है। स्नान, ब्रह्मासहित सावित्री-पूजा, जागरण और कथाश्रवण के बाद दान-भोजन हैं। ये नियम इसी व्रत के हैं; स्थानीय अमावास्या-व्रत का दिन न बदलें।","tel":"ఈ సావిత్రీవ్రతంలో త్రయోదశి నుంచి మూడు రోజుల ఉపవాసనియమం ఉంది. అశక్తులకు త్రయోదశినాడు నక్తభోజనం, చతుర్దశినాడు అయాచితభోజనం, పౌర్ణమినాడు ఉపవాసం అనే రూపం చెప్పబడింది. స్నానం, బ్రహ్మసహిత సావిత్రీపూజ, జాగరణ, కథాశ్రవణం ఆచరణలు. తరువాత దానభోజనాలు ఉన్నాయి. ఇవి ఈ వ్రతానికే వర్తిస్తాయి; స్థానిక అమావాస్య వ్రతాన్ని పౌర్ణమికి మార్చవద్దు."},"differs":true},{"id":"ashadha-purnima","key":{"masa":3},"name":{"roman":"Āṣāḍha Pūrṇimā","deva":"आषाढ़ पूर्णिमा","tel":"ఆషాఢ పౌర్ణమి"},"when":{"roman":"Guru Pūrṇimā · Vyāsa Pūrṇimā","deva":"गुरु पूर्णिमा · व्यास पूर्णिमा","tel":"గురు పౌర్ణమి · వ్యాస పౌర్ణమి"},"source":{"roman":"Mahābhārata, Ādi Parva — Ādivaṁśāvataraṇa","deva":"महाभारत, आदि पर्व — आदिवंशावतरण","tel":"మహాభారతం, ఆది పర్వం — ఆదివంశావతరణం"},"meaning":{"roman":"While narrating the Mahabharata to Janamejaya, Vaishampayana tells the accounts of Uparichara Vasu, Satyavati, Parashara and Vyasa in the Adivansavatarana portion. This is not an answer to a question about observing Guru Purnima. The epic account is included here because it explains Vyasa's role as a teacher.","deva":"जनमेजय को महाभारत सुनाते हुए वैशम्पायन आदिवंशावतरण भाग में उपरिचर वसु, सत्यवती, पराशर और व्यास का वृत्तान्त कहते हैं। यह “गुरुपूर्णिमा-व्रत कैसे करें?” प्रश्न का उत्तर नहीं है। व्यास के गुरु-स्थान को समझाने वाली इस इतिहासनिष्ठ कथा को यहाँ पर्व के साथ जोड़ा गया है।","tel":"జనమేజయునికి మహాభారతాన్ని వినిపిస్తున్న వైశంపాయనుడు ఆదివంశావతరణ భాగంలో ఉపరిచర వసువు, సత్యవతి, పరాశరుడు, వ్యాసుని వృత్తాంతాలను చెబుతాడు. ఇది “గురుపౌర్ణమి వ్రతం ఎలా చేయాలి?” అనే ప్రశ్నకు సమాధానం కాదు. గురువుగా వ్యాసుని స్థానాన్ని వివరించే ఇతిహాసకథను ఈ పర్వదినానికి అనుబంధంగా ఇస్తున్నాం."},"story":{"roman":"Satyavati, raised in a fisherman's household, helped her foster father by ferrying passengers across the Yamuna. One day sage Parashara saw her. In response to his desire, she explained her circumstances, her fear of being seen and the difficulties she would face on returning home. Parashara created a mist and granted the boons she sought. Her fish-like odour became a sweet fragrance, giving her the names Gandhavati and Yojanagandha.\n\nThrough Parashara she bore a radiant son on an island in the Yamuna. Because he was born on an island, he was called Dvaipayana. With his mother's permission he departed for austerities, promising to return whenever she remembered him in need.\n\nRecognising that human lifespan and strength diminish as the ages progress, Dvaipayana arranged the Vedas. This work gave him the name Vyasa, the arranger. He taught disciples including Sumantu, Jaimini, Paila, Shuka and Vaishampayana. Through them he also disseminated the Mahabharata. The narrative presents him as a teacher who organised knowledge and preserved it through a lineage of students.","deva":"मछुआरे के घर पली सत्यवती अपने पालक पिता की सहायता के लिए यमुना में नाव चलाती थी। एक दिन पराशर मुनि ने उसे देखा। उनकी इच्छा के उत्तर में उसने अपनी परिस्थिति, दूसरों के देखने का भय और घर लौटने पर होने वाली कठिनाइयाँ बताईं। पराशर ने कुहरा उत्पन्न किया और उसके माँगे हुए वर दिए। उसके शरीर की मछली जैसी गन्ध सुगन्ध में बदल गई; वह गन्धवती और योजनगन्धा कहलायी।\n\nपराशर से उसे यमुना के द्वीप पर तेजस्वी पुत्र हुआ। द्वीप में जन्म लेने के कारण उसका नाम द्वैपायन पड़ा। माता की अनुमति से तपस्या के लिए जाते समय उसने वचन दिया कि आवश्यकता में उसका स्मरण करने पर वह उपस्थित होगा।\n\nयुगों के साथ मनुष्यों की आयु और शक्ति घटती देखकर द्वैपायन ने वेदों को व्यवस्थित किया। इससे वे व्यास कहलाए। उन्होंने सुमन्तु, जैमिनि, पैल, शुक और वैशम्पायन जैसे शिष्यों को ज्ञान दिया। उनके माध्यम से महाभारत का भी प्रसार किया। कथा उन्हें ऐसे गुरु के रूप में प्रस्तुत करती है जिन्होंने ज्ञान को क्रमबद्ध किया और शिष्यपरम्परा में सुरक्षित रखा।","tel":"మత్స్యకారుని వద్ద పెరిగిన సత్యవతి తన పెంపుడు తండ్రికి సహాయంగా యమునలో పడవ నడిపేది. ఒకరోజు పరాశర మహర్షి ఆమెను చూశాడు. ఆయన అభిలాషకు సమాధానంగా సత్యవతి తన స్థితి, ఇతరులు చూస్తారనే భయం, ఇంటికి తిరిగివెళ్లినప్పుడు కలిగే సమస్యలను వివరించింది. పరాశరుడు పొగమంచును సృష్టించి, ఆమె కోరిన వరాలను ఇచ్చాడు. ఆమె శరీరంలోని చేపవాసన సువాసనగా మారి గంధవతి, యోజనగంధ అనే పేర్లు పొందింది.\n\nపరాశరుని ద్వారా ఆమెకు యమునలోని ద్వీపంపై తేజోవంతుడైన కుమారుడు జన్మించాడు. ద్వీపంలో జన్మించినందువల్ల ద్వైపాయనుడు అనే పేరు వచ్చింది. తల్లి అనుమతితో తపస్సుకు బయలుదేరుతూ అవసరమైనప్పుడు తనను తలచుకుంటే వచ్చేస్తానని చెప్పాడు.\n\nయుగాలు గడిచేకొద్దీ మానవుల ఆయుష్షు, బలం తగ్గుతాయని గుర్తించిన ద్వైపాయనుడు వేదాలను క్రమబద్ధీకరించాడు. అందువల్ల వ్యాసుడు అనే పేరు పొందాడు. సుమంతుడు, జైమిని, పైలుడు, శుకుడు, వైశంపాయనుడు వంటి శిష్యులకు జ్ఞానాన్ని బోధించాడు. మహాభారతాన్ని కూడా వారి ద్వారా ప్రచారం చేశాడు. జ్ఞానం అందుబాటులో ఉండేలా క్రమపరచి, శిష్యపరంపర ద్వారా నిలిపిన గురువుగా ఈ కథ ఆయనను పరిచయం చేస్తుంది."},"connection":{"roman":"Ashadha Purnima is celebrated as Guru Purnima and Vyasa Purnima. However, this birth account gives neither the month Ashadha nor a full-moon tithi. The traditional birthday association should be distinguished from what the epic passage explicitly states.","deva":"आषाढ़ पूर्णिमा गुरुपूर्णिमा और व्यासपूर्णिमा के नाम से मनाई जाती है। पर इस जन्मवृत्तान्त में आषाढ़ मास या पूर्णिमा तिथि नहीं दी गई है। पारम्परिक जन्मोत्सव-संबंध और महाभारत के स्पष्ट कथन में अन्तर रखना चाहिए।\n\n<a id=\"purnima-05\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"ఆషాఢ పౌర్ణమి గురువులను స్మరించే గురుపౌర్ణమిగా, వ్యాసపౌర్ణమిగా ప్రసిద్ధి. కానీ పై జన్మకథలో ఆషాఢమాసం లేదా పౌర్ణమి తిథి లేదు. వ్యాసుని జన్మతిథి అనే ఆచారసంబంధాన్ని, ఇతిహాసంలో ప్రత్యక్షంగా చెప్పిన వివరాన్ని వేరుగా గుర్తించాలి."},"niyama":{"roman":"Worship Vyasa and one's guru lineage; recitation of the Guru Parampara Stotra is an attested practice. At Sringeri, the Jagadgurus take the Chaturmasya vow after Vyasa Puja, remaining in one place for contemplation and Vedantic reflection. This monastic vow is not automatically binding on householders. The institutional source specifies no universal fast or fast-breaking time.","deva":"व्यास और अपनी गुरु-परम्परा की पूजा तथा गुरु-परम्परा-स्तोत्र का पाठ प्रचलित आचरण हैं। शृङ्गेरी में जगद्गुरु व्यासपूजा के बाद चातुर्मास्य-सङ्कल्प लेकर एक स्थान पर रहते हुए ध्यान और वेदान्त-विचार करते हैं। यह संन्यास-परम्परा का सङ्कल्प सभी गृहस्थों पर अनिवार्य नहीं है। स्रोत सबके लिए एक उपवास या पारण-समय नहीं निर्धारित करता।","tel":"వ్యాసుని, తమ గురుపరంపరను పూజించి గురుపరంపర స్తోత్రం పఠించడం సంప్రదాయ ఆచరణ. శ్రీశృంగేరి పీఠంలో ఈ రోజున వ్యాసపూజ అనంతరం జగద్గురువులు చాతుర్మాస్య సంకల్పం చేసి ఒకేచోట నివసిస్తూ ధ్యానవేదాంత విచారణకు సమయం కేటాయిస్తారు. ఈ సన్న్యాస సంప్రదాయ సంకల్పాన్ని గృహస్థులందరికీ తప్పనిసరి నియమంగా చెప్పకూడదు. పరిశీలించిన ఆధారం అందరికీ ఒకే ఉపవాసం లేదా పారాణ సమయం నిర్ణయించదు."},"differs":true},{"id":"shravana-purnima","key":{"masa":4},"name":{"roman":"Śrāvaṇa Pūrṇimā","deva":"श्रावण पूर्णिमा","tel":"శ్రావణ పౌర్ణమి"},"when":{"roman":"Hayagrīva Jayantī · Upākarma · Rakṣā Bandhana","deva":"हयग्रीव जयन्ती · उपाकर्म · रक्षा बन्धन","tel":"హయగ్రీవ జయంతి · ఉపాకర్మ · రక్షాబంధనం"},"source":{"roman":"Devī Bhāgavata Purāṇa 1.5","deva":"देवी भागवत पुराण १.५","tel":"దేవీ భాగవత పురాణం 1.5"},"meaning":{"roman":"The sages ask Suta how Vishnu, the cause of all things, could lose his head and become known as Hayagriva. Suta asks them to listen attentively and recounts the event.","deva":"ऋषि सूत से पूछते हैं कि सबके कारण भगवान विष्णु का सिर कैसे अलग हुआ और वे हयग्रीव कैसे कहलाए। सूत उन्हें ध्यानपूर्वक सुनने को कहते हैं और वृत्तांत बताते हैं।","tel":"ఋషులు సూతుణ్ని, “సమస్తానికి కారణమైన విష్ణువు శిరస్సు ఎలా వేరయింది? ఆయన హయగ్రీవుడిగా ఎలా ప్రసిద్ధుడయ్యాడు? ఈ ఆశ్చర్యకరమైన వృత్తాంతాన్ని వివరించండి” అని అడుగుతారు. సూతుడు శ్రద్ధగా వినమని చెప్పి కథను వివరిస్తాడు."},"story":{"roman":"Exhausted after a prolonged battle, Vishnu slept with his head resting against a bow standing on the ground. The gods, engaged in a sacrifice, came seeking him. They hesitated to disturb his sleep. Brahma eventually created a vamri insect to gnaw the bow. When it sprang loose, a terrible sound arose and Vishnu's head was severed.\n\nThe gods were distressed. At Brahma's direction, the personified Vedas praised Mahamaya. The Goddess responded and explained the causes behind the event. She mentioned a curse Lakshmi had pronounced under a tamasic influence after misunderstanding Vishnu's laughter. She then described the demon Hayagriva.\n\nHe had pleased the Goddess through austerities and requested immortality. Told that birth inevitably entails death, he instead asked to die only at the hands of someone with a horse's head. Armed with this boon, he oppressed gods and sages.\n\nThe Goddess instructed that a horse's head be fitted to Vishnu's body. Vishvakarma carried this out. By her grace, Vishnu assumed the horse-headed form of Hayagriva. He subsequently slew the demon Hayagriva and accomplished the gods' purpose.","deva":"लंबे युद्ध के बाद थके हुए विष्णु भूमि पर खड़े धनुष के सहारे सिर रखकर सो गए। यज्ञ कर रहे देवता उन्हें खोजते हुए वहाँ आए। वे उनकी निद्रा भंग करने में संकोच कर रहे थे। अंत में ब्रह्मा ने वम्री नाम का कीड़ा उत्पन्न करके धनुष को कुतरवाया। धनुष अचानक छूटा, भयंकर शब्द हुआ और विष्णु का सिर अलग हो गया।\n\nदेवता दुखी हुए। ब्रह्मा के निर्देश पर मूर्तिमान वेदों ने महामाया की स्तुति की। देवी प्रसन्न हुईं और इस घटना के कारण बताए। उन्होंने विष्णु की हँसी का गलत अर्थ समझकर तामसी शक्ति के प्रभाव में लक्ष्मी द्वारा दिए गए शाप का उल्लेख किया। फिर हयग्रीव नामक दैत्य की बात बताई।\n\nउसने तपस्या से देवी को प्रसन्न करके अमरत्व माँगा था। देवी ने बताया कि जन्म लेने वाले की मृत्यु निश्चित है। तब उसने केवल घोड़े के मुख वाले व्यक्ति के हाथों मृत्यु का वर माँगा। इस वर के बल पर वह देवताओं और ऋषियों को सताने लगा।\n\nदेवी ने विष्णु के शरीर पर घोड़े का सिर लगाने को कहा। विश्वकर्मा ने ऐसा किया। देवी की कृपा से विष्णु हयग्रीव रूप में प्रकट हुए। बाद में उन्होंने दैत्य हयग्रीव का वध करके देवताओं का कार्य पूरा किया।","tel":"దీర్ఘకాల యుద్ధంతో అలసిన విష్ణువు, నేలపై నిలిపిన వింటిపై తల ఆనించి నిద్రించాడు. యజ్ఞాన్ని నిర్వహిస్తున్న దేవతలు ఆయనను కోరుతూ వచ్చారు. నిద్రాభంగం చేయడానికి సంకోచించారు. చివరకు బ్రహ్మ వమ్రీ అనే పురుగును సృష్టించి వింటిని కొరికించాడు. విల్లు ఒక్కసారిగా విడివడగా ఘోరమైన ధ్వని వచ్చింది; విష్ణువు శిరస్సు వేరయింది.\n\nదేవతలు కలత చెందారు. బ్రహ్మ సూచనతో వేదాలు మహామాయను స్తుతించాయి. దేవి ప్రసన్నురాలై, ఈ సంఘటన వెనుక కారణాలను వివరించింది. విష్ణువు నవ్వును అపార్థం చేసుకున్న లక్ష్మి, తామసశక్తి ప్రభావంతో పలికిన శాపాన్ని పేర్కొంది. తరువాత హయగ్రీవుడనే దైత్యుని విషయాన్ని చెప్పింది.\n\nఆ దైత్యుడు దేవిని తపస్సుతో ప్రసన్నం చేసుకొని అమరత్వం కోరాడు. జన్మించినవారికి మరణం తప్పదని దేవి చెప్పగా, గుర్రపుముఖం కలవాని చేతిలో మాత్రమే మరణం రావాలని కోరాడు. ఆ వరంతో దేవతలను, ఋషులను బాధించసాగాడు.\n\nవిష్ణువు దేహానికి గుర్రపు శిరస్సును అమర్చమని దేవి సూచించింది. విశ్వకర్మ ఆ ప్రకారం చేశాడు. దేవి అనుగ్రహంతో విష్ణువు హయగ్రీవరూపాన్ని పొందాడు. తరువాత దైత్య హయగ్రీవుణ్ని సంహరించి దేవతల కార్యాన్ని నెరవేర్చాడు."},"connection":{"roman":"This is a scriptural account of Hayagriva's manifestation. Its association with Shravana Purnima belongs to the festival tradition; this chapter does not explicitly name that tithi. Upakarma dates follow the rules of the respective Vedic branches.","deva":"यह हयग्रीव के प्राकट्य की पुराणकथा है। श्रावण पूर्णिमा पर हयग्रीव जयंती मनाना उत्सव-परंपरा का संबंध है; इस अध्याय में वह तिथि सीधे नहीं कही गई। उपाकर्म की तिथियाँ वेदशाखाओं के नियमों पर निर्भर होती हैं।\n\n<a id=\"purnima-06\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"ఇది హయగ్రీవావిర్భావ పురాణకథ. శ్రావణ పౌర్ణమిని హయగ్రీవ జయంతిగా ఆచరించడం సంప్రదాయ సంబంధం; ఈ అధ్యాయంలో ఆ తిథి నేరుగా పేర్కొనబడలేదు. ఉపాకర్మకు వేదశాఖలవారీగా తేదీనియమాలు ఉంటాయి."},"niyama":{"roman":"Upakarma belongs to the practitioner's initiated Vedic discipline: follow the teacher's branch-specific date and ritual, including bathing, daily duties, renewal of the sacred thread, rishi tarpana and renewed study. Thread replacement alone is incomplete. The separate Gayatri Japam observance commonly falls the next day; follow one's received instruction rather than a universal count. Hayagriva worship and Raksha Bandhan retain their distinct festival practices. No waterless fast is established for all participants.","deva":"उपनयन और अपनी वेदशाखा के अनुष्ठान से सम्बद्ध उपाकर्म आचार्य के निर्देश पर करें—स्नान, नित्यकर्म, नया यज्ञोपवीत, ऋषितर्पण और अध्ययन का पुनःआरम्भ। केवल जनेऊ बदलना पूरा उपाकर्म नहीं। शाखाओं की तिथियाँ भिन्न हो सकती हैं। विशेष गायत्री-जप सामान्यतः अगले दिन होता है; उपदेश के अनुसार विधि और संख्या रखें। हयग्रीव-पूजा तथा रक्षाबन्धन अलग परम्पराएँ हैं; सबके लिए निर्जल उपवास निर्धारित नहीं किया गया।","tel":"ఉపనయనం పొంది తమ వేదశాఖ అనుష్ఠానం చేసే వారు ఆచార్యుని సూచనతో ఉపాకర్మ చేయాలి: స్నానం, నిత్యకర్మ, నూతన యజ్ఞోపవీతధారణ, ఋషితర్పణం, వేదాధ్యయన పునఃప్రారంభం. జంధ్యం మార్చుకోవడమే పూర్తి ఉపాకర్మ కాదు. ఋగ్–యజుః–సామవేద శాఖలకు ఒకే తేదీని వర్తింపజేయకూడదు. ప్రత్యేక గాయత్రీజపదినం శ్రావణ ఉపాకర్మ తరువాతి రోజుగా అనేక సంప్రదాయాల్లో ఉంటుంది; దానిని పౌర్ణమి రోజుకే తప్పనిసరిగా చేర్చకూడదు. ఉపదేశం పొందిన వారు తమ ఆచార్యుడు చెప్పిన సంఖ్య, విధానాన్ని అనుసరించాలి. హయగ్రీవ జయంతి ఆచరించే వారు హయగ్రీవారాధన, స్తోత్రపఠనం చేయవచ్చు. రక్షాబంధనం కుటుంబ/ప్రాంత సంప్రదాయం. వీటన్నింటికీ ఒకే నిర్జల ఉపవాసం నిర్ధారించలేదు."},"differs":true},{"id":"bhadrapada-purnima","key":{"masa":5},"name":{"roman":"Bhādrapada Pūrṇimā","deva":"भाद्रपद पूर्णिमा","tel":"భాద్రపద పౌర్ణమి"},"when":{"roman":"Bhāgavata dāna · Umā-Maheśvara Vrata","deva":"भागवत दान · उमा-महेश्वर व्रत","tel":"భాగవత దానం · ఉమామహేశ్వర వ్రతం"},"source":{"roman":"Śrīmad Bhāgavata — 1.7 and 12.13.13","deva":"श्रीमद्भागवत — १.७ और १२.१३.१३","tel":"శ్రీమద్భాగవతం — 1.7, 12.13.13"},"meaning":{"roman":"In the assembly of sages at Naimisharanya, Shaunaka asks Suta when, where and why the Bhagavata was composed, and what inspired Vyasa to undertake it. Suta recounts Vyasa's meeting with Narada.","deva":"नैमिषारण्य की ऋषिसभा में शौनक सूत से पूछते हैं कि भागवत कब, कहाँ और क्यों रचा गया तथा व्यास को इसकी प्रेरणा कैसे मिली। सूत व्यास और नारद की भेंट का वृत्तांत बताते हैं।","tel":"నైమిశారణ్యంలోని ఋషుల సభలో శౌనకుడు సూతుణ్ని, “భాగవతం ఎప్పుడు, ఎక్కడ, ఏ కారణంతో రూపొందింది? వ్యాసునికి దానిని రచించే ప్రేరణ ఎలా కలిగింది?” అని అడుగుతాడు. సూతుడు వ్యాసుడు–నారదుని సంభాషణను చెబుతాడు."},"story":{"roman":"Recognizing humanity's diminishing capacity, Vyasa divided the Veda into four and entrusted their teaching to his disciples. He also composed the Mahabharata to make its meaning accessible more widely. Yet he remained inwardly dissatisfied.\n\nWhile reflecting on his work beside the Sarasvati, he was visited by Narada. Narada asked about his dissatisfaction. Vyasa explained that, although he had expounded many duties and teachings, his heart was still unsettled.\n\nNarada identified the deficiency: Vyasa had not sufficiently celebrated the Lord's unblemished glory. His exposition of devotion did not match the attention he had given to other human aims. Narada also recounted how serving devotees and hearing sacred accounts had transformed him in his previous life.\n\nAfter Narada departed, Vyasa meditated and perceived the Lord and the divine power under his control. He understood the suffering caused by ignorance and how devotional yoga could alleviate it. With this insight, he composed the Bhagavata and taught it to Shuka.","deva":"लोगों की घटती क्षमता देखकर व्यास ने वेद को चार भागों में बाँटा और शिष्यों को उनके अध्ययन-अध्यापन का दायित्व दिया। वेद का अर्थ अधिक लोगों तक पहुँचाने के लिए महाभारत भी रचा। फिर भी उन्हें भीतर से संतोष नहीं मिला।\n\nसरस्वती के तट पर अपने कार्य का विचार करते समय नारद उनके आश्रम आए। नारद ने उनकी असंतुष्टि के बारे में पूछा। व्यास ने कहा कि अनेक धर्मों और विषयों का वर्णन करने पर भी उनका मन शांत नहीं हुआ है।\n\nनारद ने बताया कि भगवान के निर्मल यश का पर्याप्त वर्णन न करना उनकी रचना की कमी है। अन्य पुरुषार्थों का जितना विस्तार किया गया है, उतना भगवद्भक्ति का नहीं हुआ। नारद ने यह भी सुनाया कि पिछले जन्म में भक्तों की सेवा और भगवान की कथाएँ सुनने से उनका जीवन कैसे बदला।\n\nनारद के जाने पर व्यास ने ध्यान किया। उन्होंने भगवान और उनके अधीन माया को देखा। उन्हें समझ में आया कि अज्ञान जीव को दुख देता है और भक्तियोग उसका निवारण करता है। इस अनुभूति से उन्होंने भागवत संहिता रची और शुक को पढ़ाई।","tel":"ప్రజల సామర్థ్యం తగ్గుతున్నదని గ్రహించిన వ్యాసుడు వేదాన్ని నాలుగు భాగాలుగా విభజించాడు. శిష్యులకు వాటి అధ్యయన బాధ్యతలు అప్పగించాడు. వేదార్థం అందరికీ సులభంగా చేరేందుకు మహాభారతాన్ని కూడా రచించాడు. అయినా అతని మనస్సులో తృప్తి కలగలేదు.\n\nసరస్వతీ తీరాన తన కార్యాన్ని ఆలోచిస్తున్నప్పుడు నారదుడు ఆశ్రమానికి వచ్చాడు. వ్యాసుణ్ని అతని అసంతృప్తి గురించి అడిగాడు. వ్యాసుడు ఎన్నో ధర్మాలను వివరించినా తన అంతరంగం ఇంకా ప్రశాంతంగా లేదని చెప్పాడు.\n\nనారదుడు, భగవంతుని నిర్మలమైన యశస్సును పూర్తిగా కీర్తించకపోవడమే లోటని వివరించాడు. ధర్మార్థకామాల వివరణలో ఉన్న విస్తృతితో సమానంగా భగవద్భక్తిని చెప్పలేదని సూచించాడు. తన పూర్వజన్మలో భక్తుల సేవ, భగవత్కథాశ్రవణం తనను ఎలా మార్చాయో కూడా తెలిపాడు.\n\nనారదుడు వెళ్లిన తరువాత వ్యాసుడు ధ్యానంలో భగవంతుణ్ని, ఆయన ఆధీనంలోని మాయను దర్శించాడు. అజ్ఞానంతో జీవుడు బాధపడుతున్నాడని, భక్తియోగం ఆ బాధను తొలగిస్తుందని తెలుసుకున్నాడు. ఈ అవగాహనతో భాగవత సంహితను రూపొందించి శుకునికి బోధించాడు."},"connection":{"roman":"Bhagavatam 12.13.13 specifically praises gifting the Bhagavata on Bhadrapada Purnima with a golden lion, interpreted in the consulted edition as a golden throne. It is a prescription for scriptural donation, not a separate monthly story. The composition narrative is not said to have occurred on this date.","deva":"भागवत 12.13.13 में भाद्रपद पूर्णिमा पर स्वर्णसिंह सहित भागवत दान का माहात्म्य है। उद्धृत अंग्रेज़ी संस्करण इसे स्वर्णसिंहासन मानता है। यह ग्रंथदान का विधान है, अलग मासिक व्रतकथा नहीं। ऊपर का रचना-वृत्तांत उसी तिथि का बताया नहीं गया है।\n\n<a id=\"purnima-07\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"భాగవతం 12.13.13 భాద్రపద పౌర్ణమినాడు భాగవతగ్రంథాన్ని స్వర్ణసింహంతో కూడి దానం చేయడాన్ని కీర్తిస్తుంది. ఇది గ్రంథదాన మాహాత్మ్యం. పై రచనావృత్తాంతం అదే రోజున జరిగిందని మూలం చెప్పదు; ప్రత్యేక కల్పిత వ్రతకథను దానికి జోడించలేదు."},"niyama":{"roman":"Bhagavata donation has an explicit Purana connection to this day. A simple book gift is a devotional practice, not automatically the complete golden-throne rite described in the verse. Stotra Nidhi separately lists Uma–Maheshvara Vrata and its stotram. Worship Shiva and Parvati according to the received vrata procedure; no verified compulsory fasting mode, thread count or leaf count is supplied here.","deva":"इस दिन भागवत-ग्रन्थदान का प्रत्यक्ष पुराणाधार है। साधारण पुस्तकदान भक्तिपूर्ण आचरण है; उसे श्लोक के स्वर्णासनयुक्त पूर्ण विधान के समान घोषित नहीं किया गया। स्तोत्रनिधि इस पूर्णिमा पर उमा-महेश्वर व्रत और उनका स्तोत्र देता है। अपने प्रचलित व्रतकल्प के अनुसार शिव-पार्वती की पूजा करें। उपवास के प्रकार, धागों या पत्रों की अनिवार्य संख्या का सत्यापित विधान यहाँ नहीं दिया गया।","tel":"భాగవతగ్రంథదానం ఈ పౌర్ణమికి నేరుగా పురాణాధారమున్న విశేషం. మూలంలో చెప్పిన హేమసింహసమన్విత దానాన్ని సాధారణ గ్రంథదానంతో పూర్తిగా సమానమని ప్రకటించలేదు; సాధ్యమైన గ్రంథదానం భక్తిపూర్వక ఆచరణగా చేయవచ్చు. ఉమామహేశ్వర వ్రతం తెలుగు తిథి జాబితాలో ఉంది; శివపార్వతుల పూజ, ఉమామహేశ్వర స్తోత్రపఠనం సూచించబడ్డాయి. నిర్దిష్ట ఉపవాసం, దారాల సంఖ్య, బిల్వపత్రాల సంఖ్యకు ధృవీకరించిన పూర్తి వ్రతకల్పం ఇక్కడ లభించలేదు; వాటిని తప్పనిసరి నియమాలుగా జోడించలేదు."},"differs":true},{"id":"ashvina-purnima","key":{"masa":6},"name":{"roman":"Āśvina Pūrṇimā","deva":"आश्विन पूर्णिमा","tel":"ఆశ్వయుజ పౌర్ణమి"},"when":{"roman":"Śarad Pūrṇimā · Kojāgara","deva":"शरद पूर्णिमा · कोजागर","tel":"శరద్ పౌర్ణమి · కోజాగర"},"source":{"roman":"Śrīmad Bhāgavata 10.29–33","deva":"श्रीमद्भागवत १०.२९–३३","tel":"శ్రీమద్భాగవతం 10.29–33"},"meaning":{"roman":"While narrating Krishna's pastimes to Parikshit, Shuka describes how the autumn nights and blossoming jasmine moved Krishna to undertake a pastime through Yogamaya. There is no introductory question about a monthly full-moon vow.","deva":"परीक्षित को कृष्ण की लीलाएँ सुनाते हुए शुकदेव बताते हैं कि शरद् की रातों और खिले हुए मल्लिका-पुष्पों को देखकर कृष्ण ने योगमाया के द्वारा लीला का संकल्प किया। यहाँ आरंभ में मासिक पूर्णिमा-व्रत का कोई विशेष प्रश्न नहीं है।","tel":"పరీక్షిత్తుకు కృష్ణలీలలను చెబుతున్న శుక మహర్షి, శరదృతువు రాత్రుల్లో వికసించిన మల్లెలను చూసి కృష్ణుడు యోగమాయను ఆశ్రయించి లీలకు సంకల్పించాడని వివరిస్తాడు. ఈ ప్రారంభంలో పౌర్ణమి వ్రతం గురించి ప్రత్యేక ప్రశ్న లేదు."},"story":{"roman":"The complete moon illuminated Vrindavana. Krishna played his flute, and the gopis left their activities to come to him. He told them that the forest was dangerous at night and advised them to return to their families. They pleaded that their hearts belonged to him and asked him not to reject them.\n\nHe sported with them. When his special attention gave rise to pride, he disappeared. Searching for him, they questioned trees, creepers and animals, reenacted his pastimes and followed his footprints. Finally, they assembled beside the Yamuna and sang the Gopi-gita in their anguish of separation.\n\nKrishna reappeared. In response to their questions, he explained different kinds of love and reciprocation. His absence, he said, had deepened their attachment to him. The rasa dance then began, with Krishna manifesting beside each pair of gopis. Celestial beings witnessed the dance. After the ensuing pastimes, the gopis returned home with his permission.\n\nParikshit subsequently questioned the propriety of the conduct described. Shuka distinguished the Lord's divine activity from ordinary human conduct and warned against imitation. He concluded that faithfully hearing this account develops devotion and removes desire from the heart.","deva":"पूर्ण चंद्रबिंब की ज्योति से वृन्दावन प्रकाशित था। कृष्ण ने बाँसुरी बजाई। उसकी ध्वनि सुनकर गोपियाँ अपने काम छोड़कर उनके पास आईं। कृष्ण ने रात में वन को असुरक्षित बताते हुए परिवार के पास लौटने को कहा। गोपियों ने प्रार्थना की कि उनका मन उन्हीं को समर्पित है; वे उन्हें न ठुकराएँ।\n\nकृष्ण उनके साथ विहार करने लगे। विशेष स्नेह से उनमें गर्व उत्पन्न होने पर वे अदृश्य हो गए। गोपियाँ उन्हें खोजते हुए वृक्षों, लताओं और पशुओं से पूछने लगीं। उन्होंने उनकी लीलाओं का अभिनय किया और पदचिह्नों का पीछा किया। अंत में यमुना के तट पर एकत्र होकर विरह में गोपीगीत गाया।\n\nकृष्ण फिर प्रकट हुए। उनके प्रश्नों के उत्तर में उन्होंने प्रेम और उसके प्रत्युपकार के प्रकार बताए। उन्होंने कहा कि उनका छिपना गोपियों के प्रेम को और गहरा करने के लिए था। फिर प्रत्येक दो गोपियों के बीच अपना रूप प्रकट करके रासनृत्य किया। देवताओं ने यह लीला देखी। विहार के बाद गोपियाँ उनकी अनुमति से घर लौटीं।\n\nपरीक्षित ने बाद में इस आचरण के औचित्य पर प्रश्न किया। शुकदेव ने ईश्वर की लीला और साधारण मनुष्य के आचरण का भेद बताया तथा अनुकरण से मना किया। अंत में उन्होंने कहा कि श्रद्धापूर्वक यह कथा सुनने से भक्ति बढ़ती है और हृदय का काम दूर होता है।","tel":"పూర్ణచంద్రబింబం వెలుగులో బృందావనం ప్రకాశించింది. కృష్ణుడు మధురంగా వేణువు ఊదాడు. ఆ ధ్వని విని గోపికలు తమ పనులను వదిలి ఆయన దగ్గరకు వచ్చారు. కృష్ణుడు రాత్రివేళ అడవిలో ఉండడం ప్రమాదమని, కుటుంబాల దగ్గరకు తిరిగి వెళ్లాలని చెప్పాడు. గోపికలు తమ మనస్సులు ఆయనకే అర్పితమయ్యాయని, తమను విడిచిపెట్టవద్దని ప్రార్థించారు.\n\nఆయన వారితో విహరించాడు. తన ప్రత్యేక అనుగ్రహం వల్ల గోపికల్లో గర్వం కలిగినప్పుడు అదృశ్యమయ్యాడు. ఆయనను వెదుకుతూ వారు చెట్లను, లతలను, జంతువులను అడిగారు; ఆయన లీలలను అనుకరించారు. పాదముద్రలను అనుసరించారు. చివరికి యమునాతీరానికి చేరి విరహంతో గోపికాగీతాన్ని పాడారు.\n\nకృష్ణుడు తిరిగి ప్రత్యక్షమయ్యాడు. వారి ప్రశ్నలకు సమాధానంగా ప్రేమ, ప్రత్యుపకారం గురించి వివరించాడు. తన అదృశ్యం వారి ప్రేమను మరింత గాఢం చేయడానికేనని చెప్పాడు. తరువాత ప్రతి ఇద్దరు గోపికల మధ్య తన రూపంతో నిలిచి రాసనృత్యం చేశాడు. దేవతలు ఆ లీలను దర్శించారు. విహారం అనంతరం గోపికలు ఆయన అనుమతితో ఇళ్లకు తిరిగారు.\n\nపరీక్షిత్తు ఈ ప్రవర్తన గురించి సందేహం అడిగినప్పుడు శుకుడు, ఈశ్వరలీలను సాధారణ మానవ ప్రవర్తనతో సమానంగా చూడకూడదని, అనుకరించకూడదని వివరిస్తాడు. శ్రద్ధతో ఈ లీలను వినడం భక్తిని పెంచి హృదయంలోని కామాన్ని తొలగిస్తుందని ముగిస్తాడు."},"connection":{"roman":"Tradition associates this account with Sharad Purnima. The opening verses describe autumn and a complete moon, but do not explicitly identify the tithi as Ashvina Purnima.","deva":"परंपरा इस लीला को शरद् पूर्णिमा से जोड़ती है। आरंभिक श्लोक शरद् ऋतु और पूर्ण चंद्र का वर्णन करते हैं; आश्विन पूर्णिमा की तिथि सीधे नहीं बताते।\n\n<a id=\"purnima-08\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"రాసలీలను శరద్ పౌర్ణమితో అనుసంధానించడం సంప్రదాయంలో ఉంది. పై శ్లోకాలు శరదృతువు, పూర్ణచంద్రుని వర్ణిస్తాయి; ఆశ్వయుజ పౌర్ణమి అనే తిథిని నేరుగా చెప్పవు."},"niyama":{"roman":"Kojagara tradition emphasizes Lakshmi worship at night and a devotional vigil; determine the night with Purnima at nishitha using the local calendar. Moon worship and milk/kheer placed in moonlight are regional Sharad customs, not compulsory for everyone. Rasa-lila reading is devotional remembrance. Follow the particular vow's fasting procedure; no universal waterless fast is asserted.","deva":"कोजागर परम्परा में रात्रि लक्ष्मी-पूजा और जागरण प्रमुख हैं; स्थानीय पंचाङ्ग से निशीथव्यापिनी पूर्णिमा की रात चुनें। चन्द्रपूजन और चाँदनी में दूध/खीर रखने का आचार क्षेत्रविशेष का है, सबके लिए अनिवार्य विधान नहीं। रासलीला-पाठ भक्तिपूर्ण स्मरण है। उपवास अपनी व्रतपरम्परा के अनुसार रखें; सार्वभौम निर्जल उपवास घोषित नहीं किया गया।","tel":"కోజాగర వ్రత సంప్రదాయంలో రాత్రి లక్ష్మీపూజ, జాగరణ ప్రధానమైనవి; పౌర్ణమి నిశీథకాలంలో ఉండే రాత్రిని స్థానిక పంచాంగంతో నిర్ణయించాలి. శరద్ పౌర్ణమిన చంద్రారాధన, చంద్రకాంతిలో పాలు/పాయసం ఉంచే ఆచారం కొన్ని ప్రాంతాల్లో ఉంది. ఇది ప్రాంతీయ ఆచారం; అందరూ తప్పనిసరిగా చేయాల్సిన నియమం కాదు. రాసలీల పారాయణం భక్తిపూర్వక స్మరణ. ఉపవాసం చేసే వారు తమ వ్రతపద్ధతిని అనుసరించాలి; నిర్జల ఉపవాసం అందరికీ విధించలేదు."},"differs":true},{"id":"kartika-purnima","key":{"masa":7},"name":{"roman":"Kārtika Pūrṇimā","deva":"कार्तिक पूर्णिमा","tel":"కార్తిక పౌర్ణమి"},"when":{"roman":"Tripurāri Pūrṇimā · Kārtika Dīpam","deva":"त्रिपुरारि पूर्णिमा · कार्तिक दीपम्","tel":"త్రిపురారి పౌర్ణమి · కార్తిక దీపం"},"source":{"roman":"Śiva Purāṇa, Rudra-saṁhitā, Yuddha-khaṇḍa","deva":"शिव पुराण, रुद्र-संहिता, युद्ध-खण्ड","tel":"శివ పురాణం, రుద్ర సంహిత, యుద్ధఖండం"},"meaning":{"roman":"After hearing about Shiva's household pastimes, Narada asks Brahma how Shiva destroyed three asura cities with a single arrow and what that arrow was. Brahma says he will repeat Sanatkumara's narration to Vyasa.","deva":"शिव की गृहस्थ-लीलाएँ सुनने के बाद नारद ब्रह्मा से पूछते हैं कि शिव ने तीन असुरनगरों को एक बाण से कैसे जलाया और वह बाण कैसा था। ब्रह्मा कहते हैं कि वे व्यास को सनत्कुमार द्वारा सुनाया गया वृत्तांत दोहराएँगे।","tel":"శివుని గృహస్థలీలలను విన్న నారదుడు బ్రహ్మను, “మూడు అసురనగరాలను శివుడు ఒకే బాణంతో ఎలా దహించాడు? ఆ బాణం ఎటువంటిది?” అని అడుగుతాడు. బ్రహ్మ, వ్యాసునికి సనత్కుమారుడు చెప్పిన వృత్తాంతాన్ని మళ్లీ వివరిస్తానని చెబుతాడు."},"story":{"roman":"Taraka's sons—Tarakaksha, Kamalaksha and Vidyunmalin—performed severe austerities. When Brahma appeared, they requested immortality. Told that this was impossible, they obtained three impregnable cities, destroyable only when they aligned on a rare occasion and Shiva pierced them with one arrow.\n\nAt Brahma's command, Maya built cities of gold, silver and iron. Initially, their inhabitants worshipped Shiva, performed sacrifices and practised dharma. When the gods complained of their predicament, Shiva refused to destroy people who remained righteous. Later chapters describe the inhabitants being deluded and abandoning their former religious practices and Shiva worship.\n\nFollowing the gods' prayers, preparations were made. Vishvakarma constructed a cosmic chariot incorporating the worlds, with the sun and moon as its wheels. Shiva mounted it and prepared to shoot. When the cities failed to align, a heavenly voice instructed that Ganesha be worshipped. After that worship, the cities came together.\n\nBrahma and Vishnu urged Shiva to act. He released an arrow constituted by Vishnu, with Agni at its point. The cities burned. Tarakaksha remembered Shiva at the end and prayed that his mind remain devoted to him in every birth. The text states that Maya and those who sought Shiva's refuge were protected.","deva":"तारक के पुत्र तारकाक्ष, कमलाक्ष और विद्युन्माली ने कठोर तप किया। प्रसन्न ब्रह्मा से उन्होंने अमरत्व माँगा। यह संभव न होने पर उन्होंने तीन अभेद्य नगरों का वर पाया। केवल दुर्लभ समय में तीनों के एक साथ मिलने पर शिव एक बाण से उन्हें भेद सकेंगे।\n\nब्रह्मा के आदेश पर मय ने सोने, चाँदी और लोहे के नगर बनाए। आरंभ में वहाँ शिवपूजा, यज्ञ और धर्माचरण होते थे। देवताओं ने अपनी कठिनाई बताई तो शिव ने धर्म का पालन करने वालों को मारने से मना किया। आगे के अध्यायों में नगरवासियों के मोहग्रस्त होकर पूर्वधर्म और शिवपूजा छोड़ने का वर्णन है।\n\nदेवताओं की प्रार्थना पर युद्ध की तैयारी हुई। विश्वकर्मा ने समस्त लोकों से बना दिव्य रथ तैयार किया; सूर्य और चंद्र उसके चक्र बने। शिव रथ पर चढ़कर बाण छोड़ने को तैयार हुए। नगरों के न मिलने पर आकाशवाणी ने गणेशपूजा करने को कहा। पूजा के बाद तीनों नगर एक साथ आए।\n\nब्रह्मा और विष्णु ने शिव से तुरंत कार्य करने की प्रार्थना की। शिव ने विष्णुस्वरूप तथा अग्रभाग में अग्नि वाला बाण छोड़ा। त्रिपुर भस्म हो गए। अंत में तारकाक्ष ने शिव को स्मरण करके प्रत्येक जन्म में उनके प्रति बुद्धि स्थिर रहने की प्रार्थना की। पाठ के अनुसार मय और शिव की शरण लेने वाले सुरक्षित रहे।","tel":"తారకాసురుని కుమారులు తారకాక్షుడు, కమలాక్షుడు, విద్యున్మాలి తీవ్రమైన తపస్సు చేశారు. ప్రసన్నుడైన బ్రహ్మను అమరత్వం కోరారు. అది సాధ్యం కాదని చెప్పగా మూడు దుర్భేద్య నగరాలను కోరారు. అవి అరుదైన సందర్భంలో ఒకటిగా కలిసినప్పుడు మాత్రమే శివుడు ఒకే బాణంతో వాటిని భేదించగలడనే వరాన్ని పొందారు.\n\nబ్రహ్మ ఆజ్ఞతో మయుడు బంగారు, వెండి, ఇనుప నగరాలను నిర్మించాడు. మొదట అక్కడ శివారాధన, యజ్ఞాలు, ధర్మాచరణ ఉండేవి. దేవతలు తమ కష్టాన్ని చెప్పినప్పుడు, ధర్మంగా ఉన్నవారిని సంహరించనని శివుడు చెప్పాడు. తరువాతి అధ్యాయాల్లో మాయామోహంతో అక్కడివారు తమ పూర్వధర్మాన్ని, శివారాధనను విడిచినట్లు వర్ణించబడింది.\n\nదేవతల ప్రార్థనతో యుద్ధసన్నాహం జరిగింది. విశ్వకర్మ లోకాలన్నిటితో కూడిన దివ్యరథాన్ని నిర్మించాడు; సూర్యచంద్రులు చక్రాలుగా నిలిచారు. శివుడు రథాన్ని అధిరోహించి బాణం సంధించేందుకు సిద్ధమయ్యాడు. నగరాలు కలవకపోవడంతో గణేశారాధన చేయాలనే దివ్యవాణి వినిపించింది. ఆరాధన అనంతరం మూడు నగరాలు ఒకటయ్యాయి.\n\nబ్రహ్మ, విష్ణువు సమయం వచ్చిందని ప్రార్థించారు. విష్ణుస్వరూపంతో, అగ్ని అగ్రభాగంతో కూడిన బాణాన్ని శివుడు విడిచాడు. త్రిపురాలు భస్మమయ్యాయి. తారకాక్షుడు చివరలో శివుణ్ని స్మరించి ప్రతి జన్మలో ఆయనపట్ల బుద్ధి నిలవాలని కోరాడు. మయుడు, శివుణ్ని శరణు వేడినవారు రక్షించబడ్డారని పాఠం చెబుతుంది."},"connection":{"roman":"Kartika Purnima's observance as Tripurari Purnima is a festival tradition. The consulted destruction passage does not explicitly date this event to that tithi.","deva":"कार्तिक पूर्णिमा को त्रिपुरारी पूर्णिमा मानना उत्सव-परंपरा है। उद्धृत संहार-प्रसंग इस घटना की तिथि सीधे कार्तिक पूर्णिमा नहीं बताता।\n\n<a id=\"purnima-09\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"కార్తిక పౌర్ణమిని త్రిపురారి పౌర్ణమిగా ఆచరించడం ఉత్సవసంప్రదాయం. ఈ కథను అదే తిథినాడు జరిగిందని పరిశీలించిన సంహారశ్లోకాలు నేరుగా చెప్పవు."},"niyama":{"roman":"Observe morning bathing, purity, Damodara worship and lamp offerings. Chapter 7.36–39 permits helping with others' lamps; 7.47 places the month's beacon-lamp conclusion on Purnima. Telugu Jwala Toranam follows temple practice. These verses do not mandate 365 wicks for everyone.","deva":"प्रातःस्नान, शुद्धता, दामोदर-पूजा और दीपदान करें। 7.36–39 दूसरों के दीप में सहायता करने का विकल्प देते हैं; 7.47 में मासिक आकाशदीप की पूर्णिमा पर समाप्ति है। तेलुगु ज्वालातोरणम् मन्दिर-पद्धति है। इन श्लोकों से सबके लिए 365 बातियों की अनिवार्यता सिद्ध नहीं होती।","tel":"ప్రాతఃస్నానం, శుచిత్వం, దామోదరారాధన, దీపదానం ప్రధానమైనవి. స్వయంగా దీపాలు సమర్పించలేనివారు ఇతరుల దీపాలకు వత్తులు/నూనె అందించడం లేదా వెలిగించడంలో సహాయం చేయవచ్చని 7.36–39 చెబుతాయి. 7.47లో నెలంతా ఆకాశదీపం, పౌర్ణమిన దాని సమాప్తి ఉన్నాయి. తెలుగు ఆలయాల జ్వాలాతోరణం ఆలయపద్ధతిలో జరుగుతుంది; “365 వత్తులు అందరికీ తప్పనిసరి” అని పై శ్లోకాలు చెప్పవు."},"differs":true},{"id":"margashirsha-purnima","key":{"masa":8},"name":{"roman":"Mārgaśīrṣa Pūrṇimā","deva":"मार्गशीर्ष पूर्णिमा","tel":"మార్గశిర పౌర్ణమి"},"when":{"roman":"Datta Jayantī · Annapūrṇā Jayantī","deva":"दत्त जयन्ती · अन्नपूर्णा जयन्ती","tel":"దత్త జయంతి · అన్నపూర్ణా జయంతి"},"source":{"roman":"Śrīmad Bhāgavata 4.1.15–33","deva":"श्रीमद्भागवत ४.१.१५–३३","tel":"శ్రీమద్భాగవతం 4.1.15–33"},"meaning":{"roman":"While describing the families of Kardama's daughters to Vidura, Maitreya mentions the birth of Datta, Durvasas and Soma to Atri and Anasuya. Vidura asks why the divine powers responsible for creation, preservation and dissolution were born in Atri's household. Maitreya explains their appearance.","deva":"मैत्रेय विदुर को कर्दम की पुत्रियों के वंश बताते हुए कहते हैं कि अत्रि और अनसूया के यहाँ दत्त, दुर्वासा और सोम जन्मे। विदुर पूछते हैं कि सृष्टि, पालन और संहार के अधिष्ठाता देवताओं ने अत्रि के घर जन्म क्यों लिया। मैत्रेय उनका आविर्भाव बताते हैं।","tel":"మైత్రేయుడు విదురునికి కర్దముని కుమార్తెల వంశాలను వివరిస్తూ, అత్రి–అనసూయలకు దత్తుడు, దుర్వాసుడు, సోముడు జన్మించారని చెబుతాడు. విదురుడు, “సృష్టి, స్థితి, లయలకు కారణమైన దేవతలు అత్రి ఇంటిలో జన్మించడానికి కారణమేమిటి?” అని అడుగుతాడు. మైత్రేయుడు వారి ఆవిర్భావకథను వివరిస్తాడు."},"story":{"roman":"At Brahma's direction, Atri went with Anasuya to Mount Riksha. In a flowering forest beside the Nirvindhya River, he undertook austerities. Controlling his mind through breath discipline, he stood on one leg for a hundred years, sustained by air. His resolve was to seek the Lord of the universe and receive a son equal to that Lord.\n\nThe radiance of his austerity affected the three worlds. Brahma, Vishnu and Shiva arrived with celestial attendants. Atri bowed and asked why all three had come when he had contemplated one supreme Lord. Which of them had he invoked?\n\nSmiling, the deities assured him that his sincere resolve would be fulfilled: they were the divine reality upon which he had meditated. Sons embodying their respective portions would be born and spread his renown. Soma was born through Brahma's portion, Datta, a knower of yoga, through Vishnu's, and Durvasas through Shiva's.","deva":"ब्रह्मा की प्रेरणा से अत्रि अनसूया के साथ ऋक्ष पर्वत गए। निर्विन्ध्या नदी के निकट फूलों वाले वन में उन्होंने तप शुरू किया। प्राणायाम से मन को संयमित करके वे सौ वर्ष तक एक पैर पर खड़े रहे और वायु पर निर्वाह किया। उनका संकल्प था, “मैं जगदीश्वर की शरण लेता हूँ। वे अपने समान पुत्र मुझे दें।”\n\nतप का तेज तीनों लोकों को प्रभावित करने लगा। ब्रह्मा, विष्णु और शिव दिव्य परिचरों के साथ आश्रम पहुँचे। अत्रि ने प्रणाम करके पूछा, “मैंने एक जगदीश्वर का ध्यान किया था। आप तीनों कैसे आए? मैंने आपमें से किसे बुलाया था?”\n\nदेवताओं ने मुस्कराकर कहा कि उनका सच्चा संकल्प पूरा होगा; जिस परम सत्ता का उन्होंने ध्यान किया था, वे उसी के रूप हैं। उनके अंशों से पुत्र जन्मेंगे और अत्रि की कीर्ति बढ़ाएँगे। ब्रह्मा के अंश से सोम, विष्णु के अंश से योगज्ञ दत्त और शिव के अंश से दुर्वासा जन्मे।","tel":"బ్రహ్మ సూచనతో అత్రి మహర్షి భార్య అనసూయతో ఋక్షపర్వతానికి వెళ్లాడు. నిర్వింధ్యా నదీతీరంలోని పుష్పవనంలో తపస్సు ప్రారంభించాడు. ప్రాణాయామంతో మనస్సును నియంత్రించి, వంద సంవత్సరాలు ఒంటికాలిపై నిలిచి, వాయుభక్షణంతో తపస్సు చేశాడు. “జగత్తును పాలించే పరమేశ్వరుణ్ని ఆశ్రయిస్తున్నాను. ఆయనతో సమానమైన కుమారుణ్ని నాకు ప్రసాదించుగాక” అని సంకల్పించాడు.\n\nఅతని తపోతేజస్సు మూడు లోకాలను తాకింది. బ్రహ్మ, విష్ణు, శివులు దివ్యపరివారాలతో ఆశ్రమానికి వచ్చారు. అత్రి నమస్కరించి, “నేను ఒక్క జగదీశ్వరుణ్ని ధ్యానించాను. మీరు ముగ్గురూ ఎలా వచ్చారు? నేను ఆహ్వానించినవారు మీలో ఎవరు?” అని అడిగాడు.\n\nదేవతలు చిరునవ్వుతో, “నీ సంకల్పం నెరవేరుతుంది. నీవు ధ్యానించినది మేమే. మా అంశాలతో కుమారులు జన్మించి నీ కీర్తిని విస్తరింపజేస్తారు” అని వరమిచ్చారు. అనంతరం బ్రహ్మాంశంతో సోముడు, విష్ణ్వంశంతో యోగవేత్త దత్తుడు, శివాంశంతో దుర్వాసుడు జన్మించారు."},"connection":{"roman":"Datta Jayanti is traditionally observed on Margashirsha Purnima. This calendrical association is not a date stated in the cited Bhagavata verses. The familiar account of Anasuya turning the three gods into babies is absent from this passage and has not been merged with it.","deva":"दत्तजयन्ती मार्गशीर्ष पूर्णिमा को मनाने की परम्परा है। उद्धृत भागवत श्लोक जन्म की यह तिथि नहीं बताते। अनसूया द्वारा त्रिदेवों को शिशु बनाने की प्रसिद्ध कथा इस अंश में नहीं है, इसलिए दोनों वृत्तान्तों को नहीं मिलाया गया है।\n\n<a id=\"purnima-10\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"దత్తజయంతిని మార్గశిర పౌర్ణమినాడు జరుపుకునే సంప్రదాయం ఉంది. ఈ తేదీని పై భాగవత శ్లోకాల్లోని ప్రత్యక్ష ప్రకటనగా భావించకూడదు. ఈ పాఠంలో అనసూయ త్రిమూర్తులను శిశువులుగా మార్చిన ప్రచారకథ లేదు; రెండింటిని కలపలేదు."},"niyama":{"roman":"Bathe, worship Vishnu and give according to your means. The Purana includes food gifts, feeding Brahmins and a celebration concluding a monthly vow. Mathura and Pushkara are praised; verse 17.61 allows observance elsewhere. Datta Jayanti traditions include Datta worship, chanting, charity and fasting. Follow your tradition's fasting form; no universal waterless fast or vigil is established here.","deva":"स्नान, विष्णुपूजा और सामर्थ्य के अनुसार दान करें। अन्नदान, ब्राह्मणभोजन तथा मास-व्रत की समाप्ति का उत्सव वर्णित हैं। मथुरा और पुष्कर प्रशस्त हैं; 17.61 अन्य स्थान पर भी आचरण स्वीकार करता है। दत्तजयंती पर दत्तपूजा, नामस्मरण, दान और उपवास की परम्परा है। उपवास का रूप अपनी परम्परा से लें; यहाँ सबके लिए निर्जल उपवास या जागरण सिद्ध नहीं है।","tel":"స్కాందపురాణం ప్రకారం పౌర్ణమినాడు స్నానం, విష్ణుపూజ, శక్తికి తగిన దానం చేయాలి. అన్నదానం, బ్రాహ్మణభోజనం, మాసవ్రతం ముగింపు ఉత్సవం పేర్కొన్నవి. మథుర లేదా పుష్కరం ప్రశస్తమైనా, ఇతరచోట కూడా ఆచరించవచ్చని 17.61 చెబుతుంది. దత్తజయంతికి దత్తపూజ, నామస్మరణ, దానం, ఉపవాసం ఆచరించే సంప్రదాయం ఉంది; ఉపవాస విధానాన్ని తమ సంప్రదాయం ప్రకారం ఎంచుకోవాలి. అందరికీ నిర్జల ఉపవాసం లేదా జాగరణను ఇక్కడ తప్పనిసరి చేయలేదు."},"differs":true},{"id":"pausha-purnima","key":{"masa":9},"name":{"roman":"Pauṣa Pūrṇimā","deva":"पौष पूर्णिमा","tel":"పుష్య పౌర్ణమి"},"when":{"roman":"Śākambharī Jayantī","deva":"शाकम्भरी जयन्ती","tel":"శాకంభరీ జయంతి"},"source":{"roman":"Devī Bhāgavata Purāṇa 7.28","deva":"देवी भागवत पुराण ७.२८","tel":"దేవీ భాగవత పురాణం 7.28"},"meaning":{"roman":"Janamejaya asks Vyasa why the Goddess is called Shatakshi, following the account of Harishchandra. Vyasa answers with a narrative of her compassion.","deva":"हरिश्चन्द्र का वृत्तान्त सुनने के बाद जनमेजय व्यास से पूछते हैं कि देवी को शताक्षी क्यों कहा जाता है। व्यास उनकी करुणा की कथा बताते हैं।","tel":"జనమేజయుడు వ్యాసుణ్ని, “హరిశ్చంద్రుని కథను వివరించారు. దేవికి శతాక్షి అనే పేరు ఎందుకు వచ్చింది? దాని కారణం చెప్పండి” అని అడుగుతాడు. వ్యాసుడు దేవి కరుణను తెలియజేసే వృత్తాంతాన్ని చెబుతాడు."},"story":{"roman":"Durgama, son of Ruru, believed that Vedic sacrifices sustained the gods. Through austerity he obtained control of the Vedas from Brahma. The Brahmins forgot their learning, sacrifices and daily rites ceased, and the gods weakened. In the narrative, rain stopped and a hundred-year famine followed. Rivers and reservoirs dried up; people and animals suffered from hunger and thirst.\n\nThe gods and Brahmins sought the Goddess's protection. She appeared with numerous eyes and wept at the world's suffering. For nine nights her tears brought rain and replenished the rivers. She was therefore called Shatakshi. Until fresh crops grew, she provided vegetables, fruit and roots to people, and grass to animals. Because she sustained living beings with food, she became known as Shakambhari.\n\nDurgama attacked with his army. The Goddess protected those who had sought refuge in her and fought with the powers emerging from her body. She finally killed Durgama and restored the Vedas. She instructed their custodians to preserve them carefully and remember her deeds.","deva":"रुरु के पुत्र दुर्गम ने सोचा कि वैदिक यज्ञों से देवता बल पाते हैं। तप करके उसने ब्रह्मा से वेदों पर अधिकार पाया। ब्राह्मण वेद भूल गए, यज्ञ और नित्यकर्म रुक गए तथा देवता दुर्बल हुए। कथा के अनुसार वर्षा बंद हुई और सौ वर्ष तक अकाल रहा। नदियाँ और जलाशय सूख गए; मनुष्य और पशु भूख-प्यास से पीड़ित हुए।\n\nदेवताओं और ब्राह्मणों ने देवी की शरण ली। देवी अनेक नेत्रों के साथ प्रकट हुईं और संसार का दुःख देखकर करुणा से रो पड़ीं। नौ रातों तक उनके आँसुओं से वर्षा हुई और नदियाँ भर गईं। इसलिए वे शताक्षी कहलाईं। नई फसल आने तक उन्होंने मनुष्यों को सब्जियाँ, फल और कन्द तथा पशुओं को घास दी। भोजन से सबका पोषण करने के कारण वे शाकम्भरी नाम से प्रसिद्ध हुईं।\n\nदुर्गम सेना लेकर आया। देवी ने शरणागतों की रक्षा की और अपने शरीर से प्रकट शक्तियों के साथ युद्ध किया। अंत में उन्होंने दुर्गम का वध करके वेद लौटा दिए। उन्होंने वेदों को सावधानी से सुरक्षित रखने और अपने कार्यों का स्मरण करने का उपदेश दिया।","tel":"రురుని కుమారుడైన దుర్గముడు, వేదమంత్రాలతో జరిగే యజ్ఞాల వల్ల దేవతలు బలపడతారని భావించాడు. బ్రహ్మను తపస్సుతో ప్రసన్నం చేసుకుని వేదాలపై అధికారం పొందాడు. బ్రాహ్మణులు వేదాలను మరచిపోయారు; యజ్ఞాలు, నిత్యకర్మలు నిలిచిపోయాయి. దేవతలు బలహీనులయ్యారు. కథ ప్రకారం వర్షాలు ఆగి వంద సంవత్సరాల కరువు వచ్చింది. నదులు, చెరువులు ఎండిపోయాయి; మనుష్యులు, పశువులు ఆకలి దాహాలతో బాధపడ్డారు.\n\nదేవతలు, బ్రాహ్మణులు దేవిని శరణు వేడుకున్నారు. ఆమె అనేక నేత్రాలతో ప్రత్యక్షమై లోకదుఃఖాన్ని చూసి కరుణతో కన్నీరు కార్చింది. తొమ్మిది రాత్రులు ఆ జలంతో వర్షం కురిసి నదులు నిండాయి. అందుకే ఆమెను శతాక్షి అన్నారు. కొత్త పంటలు వచ్చేంతవరకు ప్రజలకు కూరలు, పండ్లు, దుంపలు, జంతువులకు గడ్డిని అందించింది. ఆహారంతో పోషించినందుకు శాకంభరీగా ప్రసిద్ధి పొందింది.\n\nదుర్గముడు సేనతో దాడి చేశాడు. దేవి ఆశ్రయించినవారిని రక్షించి, తన నుంచి ఆవిర్భవించిన శక్తులతో యుద్ధం చేసింది. చివరకు దుర్గముణ్ని సంహరించి వేదాలను తిరిగి అందించింది. వేదాలను జాగ్రత్తగా కాపాడాలని, తన కార్యాలను స్మరించాలని ఉపదేశించింది."},"connection":{"roman":"Pausha Purnima is observed as Shakambhari Jayanti and the conclusion of Shakambhari Navratri. The cited chapter does not assign its events to that date. Its nine nights of rain should not be treated as an exact statement of the calendrical festival's duration.","deva":"पौष पूर्णिमा शाकम्भरी जयन्ती और शाकम्भरी नवरात्रि के समापन के रूप में मनाई जाती है। अध्याय घटनाओं की यही तिथि नहीं बताता। पुराण की नौ रातों की वर्षा को पंचांग वाले उत्सव की निश्चित अवधि नहीं मानना चाहिए।\n\n<a id=\"purnima-11\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"పుష్య పౌర్ణమి శాకంభరీ జయంతిగా, శాకంభరీ నవరాత్రుల ముగింపుగా ఆచరించబడుతుంది. తొమ్మిది రాత్రుల పురాణవర్షాన్ని పంచాంగంలోని నవరాత్రుల ఖచ్చితమైన వ్యవధిగా మార్చకూడదు."},"niyama":{"roman":"Families observing Shakambhari worship may honour the Goddess and read or hear her Shatakshi–Shakambhari mahatmya. The cited verses explicitly support worship and reading, throughout the year. Vegetable decoration, particular offerings and fasting should follow the temple or family practice. This chapter establishes no universal nine-day abstention from food, waterless fast or vigil for Pausha Purnima.","deva":"शाकम्भरी की उपासना करने वाले परिवार देवीपूजा और शताक्षी–शाकम्भरी माहात्म्य का पाठ या श्रवण कर सकते हैं। उद्धृत श्लोक पूजा तथा पाठ बताते हैं; ये केवल इस पूर्णिमा तक सीमित नहीं हैं। सब्जियों का शृंगार, विशेष नैवेद्य या उपवास अपने मंदिर अथवा परिवार की पद्धति से करें। इस अध्याय में सभी के लिए नौ दिन निराहार रहना, निर्जल उपवास या जागरण निर्धारित नहीं है।","tel":"శాకంభరీ ఆరాధన చేసే కుటుంబాలు దేవిని పూజించి శతాక్షీ–శాకంభరీ మాహాత్మ్యాన్ని చదవవచ్చు లేదా వినవచ్చు. దేవీభాగవతంలో ఈ పఠనం, దేవీసేవ స్పష్టంగా చెప్పబడ్డాయి; ఇవి ఈ పౌర్ణమికి మాత్రమే పరిమితం కావు. కూరగాయల అలంకరణ, ప్రత్యేక నైవేద్యం, ఉపవాసం ఉంటే తమ ఆలయ లేదా కుటుంబ పద్ధతిని అనుసరించాలి. తొమ్మిది రోజుల నిరాహారం, నిర్జల ఉపవాసం, జాగరణ అందరికీ తప్పనిసరి అన్న నియమం ఈ అధ్యాయంలో లేదు."},"differs":true},{"id":"magha-purnima","key":{"masa":10},"name":{"roman":"Māgha Pūrṇimā","deva":"माघ पूर्णिमा","tel":"మాఘ పౌర్ణమి"},"when":{"roman":"Lalitā Jayantī · Māgha snāna","deva":"ललिता जयन्ती · माघ स्नान","tel":"లలితా జయంతి · మాఘ స్నానం"},"source":{"roman":"Padma Purāṇa, Uttara-khaṇḍa 127","deva":"पद्म पुराण, उत्तर-खण्ड १२७","tel":"పద్మ పురాణం, ఉత్తరఖండం 127"},"meaning":{"roman":"As Dattatreya praises bathing in Magha, Kartavirya asks who Kanchanamalini was, who the rakshasa was, and how her gift of merit brought him liberation. Dattatreya relates an ancient account.","deva":"दत्तात्रेय माघस्नान का महत्त्व बताते हैं तो कार्तवीर्य पूछता है, “काञ्चनमालिनी कौन थी? वह राक्षस कौन था? उसके पुण्यदान से उसे सद्गति कैसे मिली?” दत्तात्रेय पुराना वृत्तान्त सुनाते हैं।","tel":"దత్తాత్రేయుడు మాఘస్నాన మహిమను చెబుతుంటే కార్తవీర్యుడు, “కాంచనమాలిని ఎవరు? ఆమె పుణ్యాన్ని పొందిన రాక్షసుడు ఎవరు? అతనికి సద్గతి ఎలా కలిగింది?” అని అడుగుతాడు. దత్తాత్రేయుడు పురాతన వృత్తాంతాన్ని వివరిస్తాడు."},"story":{"roman":"The celestial woman Kanchanamalini was travelling to Kailasa after bathing at Prayaga during Magha. Drops from her wet garment fell on an aged rakshasa and calmed his cruel mind. Astonished, he asked about the water's power.\n\nShe described her earlier birth. As a courtesan in the city of Kalinga's king, she had been proud of her beauty and accumulated wealth by deceiving people. In old age she regretted having neglected charity, devotion and kindness to living beings. The royal priest advised her to abandon wrongdoing and bathe at Prayaga. She explained that three days brought purification, followed by twenty-one days of observance that earned the merit through which she attained a celestial condition.\n\nThe rakshasa confessed his own former wrongdoing and his subsequent violence against innocent creatures. Moved by compassion, Kanchanamalini dedicated her Magha-bathing merit to him. He shed his rakshasa form and obtained a radiant divine body. Before departing, he asked for guidance so that he would not sin again. She taught him to abandon violence, serve good people, speak truth and worship Hari. He bowed and went to heaven; she continued to Shiva's abode.","deva":"अप्सरा काञ्चनमालिनी माघ में प्रयागस्नान करके कैलास जा रही थी। उसके भीगे वस्त्र से जल की बूँदें एक वृद्ध राक्षस पर पड़ीं। उसका क्रूर मन शांत हुआ। उसने आश्चर्य से उस जल का महत्त्व पूछा।\n\nउसने अपना पूर्वजन्म बताया। कलिंगराज के नगर में वेश्या के रूप में वह अपने सौन्दर्य पर गर्व करती और लोगों को धोखा देकर धन कमाती थी। वृद्धावस्था में उसे पछतावा हुआ कि उसने दान, भक्ति या जीवों का हित नहीं किया। राजपुरोहित ने गलत आचरण छोड़कर प्रयागस्नान करने को कहा। उसने बताया कि तीन दिनों में पापक्षय हुआ; फिर इक्कीस दिनों के आचरण से प्राप्त पुण्य के कारण उसे दिव्य अवस्था मिली।\n\nराक्षस ने अपने पूर्वजन्म के दुष्कर्म और निर्दोष जीवों पर की गई हिंसा स्वीकार की। करुणावश काञ्चनमालिनी ने अपना माघस्नान-पुण्य उसे दिया। उसका राक्षस शरीर छूट गया और उसे तेजस्वी दिव्य शरीर मिला। जाने से पहले उसने पूछा कि वह फिर पाप न करे, इसके लिए क्या करे। उसने जीवहिंसा छोड़ने, सज्जनों की सेवा करने, सत्य बोलने और हरि की पूजा करने का उपदेश दिया। वह प्रणाम करके स्वर्ग गया और वह शिव के धाम चली गई।","tel":"కాంచనమాలిని అనే అప్సరస మాఘమాసంలో ప్రయాగస్నానం చేసి కైలాసానికి వెళ్తోంది. ఆమె తడి వస్త్రం నుంచి నీటిబిందువులు ఒక వృద్ధ రాక్షసునిపై పడ్డాయి. అతని క్రూరమైన మనస్సు శాంతించింది. ఆశ్చర్యపడి ఆమెను ఆ జలమహిమ గురించి అడిగాడు.\n\nఆమె తన పూర్వజన్మను వివరించింది. కళింగరాజు నగరంలో వేశ్యగా జీవించి, సౌందర్యం మీద గర్వంతో ప్రజలను మోసం చేసి ధనాన్ని సంపాదించింది. వృద్ధాప్యంలో తనకు దానం, భక్తి, జీవులపట్ల మేలు ఏదీ లేదని బాధపడింది. రాజపురోహితుణ్ని ఆశ్రయించగా, దుష్కర్మలను విడిచి ప్రయాగంలో స్నానం చేయమని చెప్పాడు. ఆమె మూడు రోజుల్లో పాపక్షయం, తరువాత ఇరవై ఒక్క రోజుల ఆచరణతో పుణ్యాన్ని పొంది దివ్యస్థితిని పొందినట్లు తెలిపింది.\n\nరాక్షసుడు తన పూర్వజన్మలో చేసిన దుష్కర్మలను, తరువాత నిరపరాధ జీవులను హింసించిన బాధను ఒప్పుకున్నాడు. కాంచనమాలిని కరుణతో తన మాఘస్నాన పుణ్యాన్ని అతనికి సమర్పించింది. అతడు రాక్షసరూపాన్ని విడిచి దివ్యదేహం పొందాడు. మళ్లీ పాపం చేయకుండా ధర్మోపదేశాన్ని అడిగాడు. ఆమె జీవహింసను విడిచి, సజ్జనసేవ చేసి, సత్యం పలికి, హరిని ఆరాధించమని చెప్పింది. అతడు నమస్కరించి స్వర్గానికి వెళ్లాడు; ఆమె శివసన్నిధికి వెళ్లింది."},"connection":{"roman":"This is a story of Magha's bathing greatness. The chapter does not say that this encounter occurred specifically on Magha Purnima.","deva":"यह माघमास के स्नानमाहात्म्य की कथा है। अध्याय यह नहीं कहता कि यह घटना माघ पूर्णिमा को ही हुई थी।\n\n<a id=\"purnima-12\"></a>\n\nనియమాలు · Niyamas · नियम\n\nమూలం–శ్లోకాలు · Source and verses · मूल–श्लोक","tel":"ఇది మాఘమాస స్నానమాహాత్మ్యకథ. ఘటనను మాఘ పౌర్ణమినాడే జరిగిందని మూలం చెప్పదు."},"niyama":{"roman":"The monthly observance centres on a morning bath, remembrance of Vishnu and gifts of food, clothing or blankets according to ability. Formal votaries are given further disciplines: relinquishing one food, three daily Vishnu worships, sesame–ghee offerings, a continuous lamp and sleeping on the ground. These are not imposed on every full-moon worshipper. Verse 127.23 also recognises a warm-water bath at home. Follow the adopted vow's conclusion; its Ekadashi reference is not a Purnima fast-breaking time.","deva":"मासिक आचरण में प्रातःस्नान, विष्णुस्मरण और सामर्थ्य के अनुसार अन्न, वस्त्र या कम्बल का दान है। विशेष मास-व्रती के लिए एक खाद्य वस्तु छोड़ना, त्रिकाल विष्णुपूजा, तिल–घृत होम, अखण्डदीप और भूमि पर सोना जैसे नियम दिए हैं। इन्हें प्रत्येक पूर्णिमा-भक्त पर अनिवार्य न मानें। 127.23 घर में गर्म जल से स्नान भी स्वीकार करता है। अपने व्रत का निर्धारित समापन करें; वहाँ की एकादशी का उल्लेख पूर्णिमा-पारणा का समय नहीं है।","tel":"మాఘాచరణలో ఉదయస్నానం, విష్ణుస్మరణ, శక్తికి తగిన అన్నం–వస్త్రం–కంబళి దానం చేయాలి. ప్రత్యేక మాసవ్రతం తీసుకున్నవారికి ఒక ఆహారపదార్థం విడిచిపెట్టడం, త్రికాల విష్ణుపూజ, నువ్వులు–నెయ్యి హోమం, అఖండదీపం, నేలపై నిద్ర వంటి నియమాలు పేర్కొన్నవి. ఇవన్నీ ప్రతి పౌర్ణమి భక్తుడికీ ఒకేరోజు తప్పనిసరి అనే అర్థం కాదు. 127.23 ఇంటిలో వేడినీటి స్నానాన్నీ గుర్తిస్తుంది. మాసవ్రత ఉద్యాపనం విషయంలో తన పద్ధతిని అనుసరించాలి; మూలంలోని ఏకాదశీ ప్రస్తావనను పౌర్ణమి పారాణ సమయంగా మార్చకూడదు."},"differs":true},{"id":"phalguna-purnima","key":{"masa":11},"name":{"roman":"Phālguna Pūrṇimā","deva":"फाल्गुन पूर्णिमा","tel":"ఫాల్గుణ పౌర్ణమి"},"when":{"roman":"Holikā Dahana","deva":"होलिका दहन","tel":"హోళికా దహనం"},"source":{"roman":"Śrīmad Bhāgavata 7.5 and 7.8","deva":"श्रीमद्भागवत ७.५ और ७.८","tel":"శ్రీమద్భాగవతం 7.5, 7.8"},"meaning":{"roman":"In the seventh book, Narada tells Yudhishthira about Hiranyakashipu and Prahlada. These chapters do not begin with a request for a Phalguna-Purnima story. They describe Prahlada's devotion, his father's opposition and divine protection.","deva":"सातवें स्कन्ध में नारद युधिष्ठिर को हिरण्यकशिपु और प्रह्लाद का वृत्तान्त सुनाते हैं। ये अध्याय “फाल्गुन पूर्णिमा की कथा बताइए” वाले प्रश्न से नहीं शुरू होते। इनमें प्रह्लाद की भक्ति, पिता का विरोध और भगवान की रक्षा वर्णित है।","tel":"ఏడవ స్కంధంలో నారదుడు యుధిష్ఠిరునికి హిరణ్యకశిపు–ప్రహ్లాదుల వృత్తాంతాన్ని చెబుతాడు. ఇది “ఫాల్గుణ పౌర్ణమి కథ చెప్పండి” అనే ప్రత్యేక ప్రశ్నతో ప్రారంభమయ్యే అధ్యాయం కాదు. ప్రహ్లాదుని భక్తి, తండ్రి వ్యతిరేకత, భగవంతుని రక్షణను వివరించే భాగం."},"story":{"roman":"Hiranyakashipu sent his son to Shanda and Amarka for education. Prahlada's mind, however, remained devoted to Vishnu. Asked what was the best thing he had learnt, he described nine forms of devotion, beginning with hearing, praising and remembering Vishnu. Hiranyakashipu, who considered Vishnu his enemy, became furious.\n\nHe tried repeatedly to kill his son. Weapons, elephants, serpents, poison, fire and water failed to destroy Prahlada, who remained absorbed in the Lord. Prahlada also taught devotion to the other boys.\n\nFinally, his father demanded to know whose strength enabled him to defy royal commands. Prahlada replied that the Lord supplied strength to him, his father and everyone. Hiranyakashipu challenged him: if that Lord was everywhere, why was he not visible in the pillar? He struck it. Narasimha emerged from the pillar, vindicating his devotee's conviction. After combat, the Lord placed Hiranyakashipu on his thighs at the doorway and killed him with his claws.","deva":"हिरण्यकशिपु ने पुत्र को शण्ड और अमर्क के पास पढ़ने भेजा। प्रह्लाद का मन विष्णुभक्ति में लगा रहा। पिता ने पूछा कि उसने सबसे उत्तम क्या सीखा है। उसने विष्णु का श्रवण, कीर्तन, स्मरण आदि नौ भक्ति-माध्यम बताए। विष्णु को अपना शत्रु मानने वाला हिरण्यकशिपु क्रोधित हो गया।\n\nउसने पुत्र को मारने के अनेक प्रयास किए। शस्त्र, हाथी, सर्प, विष, अग्नि और जल जैसी विपत्तियों के बीच भी प्रह्लाद भगवान में स्थित रहा। वह दूसरे बालकों को भी भक्ति सिखाता था।\n\nअंत में पिता ने पूछा कि उसकी आज्ञा का विरोध करने का बल किसने दिया। प्रह्लाद ने कहा कि उसे, पिता को और सबको बल देने वाले भगवान ही हैं। हिरण्यकशिपु ने पूछा, “यदि वे हर जगह हैं तो इस स्तम्भ में क्यों नहीं दिखाई देते?” उसने स्तम्भ पर प्रहार किया। उसमें से नृसिंह प्रकट हुए और भक्त के विश्वास को सत्य किया। युद्ध के बाद भगवान ने द्वार पर हिरण्यकशिपु को अपनी जाँघों पर रखकर नखों से उसका वध किया।","tel":"హిరణ్యకశిపు తన కుమారుణ్ని శండామర్కుల వద్ద విద్యాభ్యాసానికి పంపాడు. కానీ ప్రహ్లాదుని మనస్సు విష్ణుభక్తిలో నిలిచింది. “నీవు నేర్చుకున్న వాటిలో ఉత్తమమైనది ఏమిటి?” అని తండ్రి అడిగినప్పుడు, విష్ణుకథలు వినడం, కీర్తించడం, స్మరించడం మొదలైన తొమ్మిది భక్తిమార్గాలను చెప్పాడు. విష్ణువును శత్రువుగా భావించిన హిరణ్యకశిపు కోపించాడు.\n\nఅతడు కుమారుణ్ని చంపడానికి అనేక మార్గాలు ప్రయత్నించాడు. ఆయుధాలు, ఏనుగులు, సర్పాలు, విషం, అగ్ని, నీరు వంటి ఆపదల మధ్య కూడా ప్రహ్లాదుడు భగవంతునిపై విశ్వాసాన్ని విడువలేదు. ఇతర బాలలకు కూడా భక్తిని బోధించాడు.\n\nచివరకు తండ్రి, “నా ఆజ్ఞను ఎదిరించడానికి నీకు బలం ఇచ్చేది ఎవరు?” అని అడిగాడు. “నాకూ, మీకూ, అందరికీ బలం ఇచ్చేది భగవంతుడే” అని ప్రహ్లాదుడు సమాధానమిచ్చాడు. “ఆయన అంతటా ఉంటే ఈ స్తంభంలో ఎందుకు కనిపించడం లేదు?” అంటూ హిరణ్యకశిపు స్తంభాన్ని కొట్టాడు. దాని నుంచి నరసింహుడు ఆవిర్భవించాడు. యుద్ధం చేసి గుమ్మం దగ్గర హిరణ్యకశిపుణ్ని తన తొడలపై ఉంచి, గోళ్లతో సంహరించాడు."},"connection":{"roman":"Phalguna Purnima is associated with Holika Dahan. The familiar festival episode in which Holika sits in a fire holding Prahlada does not appear in the cited Bhagavata chapters. It has therefore not been inserted into the Bhagavata account or attributed to those verses.","deva":"फाल्गुन पूर्णिमा होलिकादहन से जुड़ी है। होलिका द्वारा प्रह्लाद को गोद में लेकर अग्नि में बैठने का प्रसिद्ध उत्सव-प्रसंग उद्धृत भागवत अध्यायों में नहीं मिलता। इसलिए उसे इन श्लोकों की कथा में जोड़कर भागवत का मूलप्रसंग नहीं बताया गया है।","tel":"ఫాల్గుణ పౌర్ణమి హోలికాదహనంతో అనుబంధితమైనది. హోలిక ప్రహ్లాదుణ్ని ఒడిలో ఉంచుకుని అగ్నిలో కూర్చున్న ఘట్టం ప్రసిద్ధ పండుగకథ; అది పై భాగవత అధ్యాయాల్లో లేదు. దానిని భాగవత మూలవచనంగా కలపలేదు."},"festival":{"roman":"When Prahlada refused to abandon devotion to Vishnu, Hiranyakashipu sought to kill him. He enlisted his sister Holika, who believed herself protected against fire. She entered the flames with Prahlada in her lap. The child continued remembering the Lord. Holika perished, while Prahlada emerged unharmed through divine protection. Holika Dahan remembers this episode as the victory of devotion and righteousness. Traditional versions differ in how they explain Holika's protection.","deva":"प्रह्लाद ने विष्णुभक्ति नहीं छोड़ी तो हिरण्यकशिपु उसे मारना चाहता था। उसने अग्नि से सुरक्षित मानी जाने वाली अपनी बहन होलिका की सहायता ली। होलिका प्रह्लाद को गोद में लेकर जलती आग में बैठ गई। बालक भगवान का नाम स्मरण करता रहा। अंत में होलिका जल गई, जबकि भगवान की रक्षा से प्रह्लाद सकुशल बचा। होलिकादहन इस घटना को भक्ति और धर्म की विजय के रूप में स्मरण करता है। होलिका की अग्नि-सुरक्षा का कारण अलग कथनों में बदलता है।","tel":"ప్రహ్లాదుడు విష్ణుభక్తిని విడువకపోవడంతో హిరణ్యకశిపు అతనిని చంపాలని ప్రయత్నించాడు. అగ్ని నుంచి రక్షణ ఉందని భావించిన తన సోదరి హోలికను సహాయం కోరాడు. ఆమె ప్రహ్లాదుణ్ని ఒడిలో ఉంచుకుని మండుతున్న అగ్నిలో కూర్చుంది. బాలుడు భగవంతుని నామాన్ని స్మరిస్తూనే ఉన్నాడు. చివరకు హోలిక దహనమైంది; ప్రహ్లాదుడు భగవంతుని రక్షణతో క్షేమంగా బయటపడ్డాడు. ఈ ఘట్టాన్ని స్మరించే హోలికాదహనం, భక్తి–ధర్మాల విజయానికి ప్రతీకగా ఆచరించబడుతుంది. హోలిక రక్షణకు సంబంధించిన వివరాలు సంప్రదాయ కథనాల్లో మారుతాయి."},"niyama":{"roman":"Where Holika Dahan is observed, prefer the evening Pradosha period with Purnima prevailing. Bhadra requires special timing decisions; avoid Bhadra Mukha and follow the locally published Holika muhurta. The colour festival and bonfire can have different dates. No universal waterless fast or night vigil is established here. For Lakshmi Jayanti, Stotra Nidhi offers Lakshmi hymns as recitation choices rather than mandatory fasting instructions.","deva":"होलिकादहन के लिए पूर्णिमा-व्याप्त प्रदोषकाल को प्राथमिकता दें। भद्रा होने पर समय-निर्णय के विशेष नियम हैं; भद्रामुख छोड़कर अपने स्थान का प्रकाशित मुहूर्त लें। रंगों की होली और दहन की तिथियाँ अलग हो सकती हैं। सभी के लिए निर्जल उपवास या रात्रिजागरण यहाँ प्रमाणित नहीं है। लक्ष्मीजयंती के लिए स्तोत्रनिधि लक्ष्मीस्तोत्र सुझाता है; यह अनिवार्य व्रत-नियमों की सूची नहीं है।","tel":"హోలికాదహనం చేసే చోట పౌర్ణమి తిథి ఉన్న ప్రదోషకాలానికి ప్రాధాన్యం ఇవ్వాలి. భద్రా ఉన్నప్పుడు ముహూర్తానికి ప్రత్యేక నియమాలు ఉంటాయి; భద్రాముఖాన్ని విడిచిపెట్టాలి. అందువల్ల తమ ప్రాంతానికి ప్రకటించిన హోలికాదహన ముహూర్తాన్ని అనుసరించాలి. రంగుల పండుగ తేదీ, దహనం తేదీ వేరు కావచ్చు. ఈ రోజుకు అందరికీ నిర్జల ఉపవాసం లేదా జాగరణ అనే నియమం ఇక్కడ నిర్ధారణ కాలేదు. లక్ష్మీజయంతిని ఆచరించేవారికి స్తోత్రనిధి లక్ష్మీస్తోత్రాలను సూచిస్తుంది; అది తప్పనిసరి వ్రతనియమాల జాబితా కాదు."},"differs":true},{"id":"adhika-purnima","key":{"adhika":true},"name":{"roman":"Adhika-māsa Pūrṇimā","deva":"अधिकमास पूर्णिमा","tel":"అధికమాస పౌర్ణమి"},"when":{"roman":"Puruṣottama māsa","deva":"पुरुषोत्तम मास","tel":"పురుషోత్తమ మాసం"},"source":{"roman":"Puruṣottama-māsa tradition — Padma Purāṇa, attributed","deva":"पुरुषोत्तम-मास परम्परा — पद्म पुराण, अनुश्रुत","tel":"పురుషోత్తమమాస సంప్రదాయం — పద్మ పురాణం, ఆపాదితం"},"meaning":{"roman":"The additional full moon of an intercalary month. This is a devotional summary about Purushottama month, not a separate Purnima vrata story. The modern publication linked below attributes it to the Padma Purana, but an exact primary chapter and verse location was not verified here. Its attribution should therefore be treated differently from the verified textual references elsewhere.","deva":"अधिकमास की अतिरिक्त पूर्णिमा। यह पुरुषोत्तममास से सम्बन्धित भक्तिपरम्परा का कथासार है, अलग पूर्णिमा-व्रत-कथा नहीं। नीचे दिया आधुनिक प्रकाशन इसे पद्मपुराण से जोड़ता है; यहाँ मूल के निश्चित अध्याय और श्लोक-संख्या का सत्यापन नहीं हुआ। अतः इसकी स्रोत-स्थिति अन्य सत्यापित ग्रन्थ-सन्दर्भों से अलग है।","tel":"అధికమాసంలోని అదనపు పౌర్ణమి. కిందిది పురుషోత్తమమాసంతో సంబంధమున్న భక్తి సంప్రదాయ కథాసారం; ప్రత్యేక పౌర్ణమి వ్రతకథ కాదు. ఇచ్చిన ఆధునిక ప్రచురణ దీనిని పద్మపురాణానికి ఆపాదిస్తుంది; నిర్దిష్ట మూలాధ్యాయం, శ్లోకాలను ఇక్కడ నిర్ధారించలేదు. అందువల్ల ఇతర విభాగాల మాదిరిగా ధృవీకరించిన పురాణసూచనగా చూడకూడదు."},"story":{"roman":"Feeling rejected and without a presiding deity, the extra month sought Vishnu’s protection. Vishnu brought it to Krishna. Krishna accepted it and bestowed his name, Purushottama. The neglected month became honoured as a special time for devotion. This story concerns the whole month, rather than its full moon alone.","deva":"उपेक्षित और अधिष्ठाता देवता से रहित अधिकमास विष्णु की शरण गया। विष्णु उसे कृष्ण के पास ले गए। कृष्ण ने उसे अपनाकर अपना पुरुषोत्तम नाम दिया। उपेक्षित मास भक्ति के विशेष अवसर के रूप में सम्मानित हुआ। यह कथा पूरे मास की है, केवल उसकी पूर्णिमा की नहीं।","tel":"తనకు గౌరవం, అధిష్ఠానదేవత లేరని అధికమాసం విష్ణువును ఆశ్రయించింది. విష్ణువు దానిని కృష్ణుని వద్దకు తీసుకెళ్ళాడు. కృష్ణుడు తన పురుషోత్తమ నామాన్ని ఇచ్చి ఆ మాసాన్ని స్వీకరించాడు. అవమానించబడిన మాసం భక్తికి ప్రత్యేకమైన కాలంగా గౌరవింపబడింది. ఇది మాసమంతటికీ సంబంధించిన కథ; పౌర్ణమికి మాత్రమే కాదు."},"connection":{"roman":"","deva":"","tel":""},"niyama":{"roman":"Continue the vow adopted for Purushottama month on its full moon. TOVP's Gaudiya guidance recommends Krishna-name chanting, Bhagavata reading, Radha–Krishna worship, lamps and Tulasi service. It suggests 33 lamps on an auspicious day, including Purnima; this is that tradition's recommendation. Its dietary programme is chosen according to ability. A separate mandatory Adhika-Purnima waterless fast, vigil or exact fast-breaking hour has not been verified.","deva":"पुरुषोत्तम मास का लिया हुआ संकल्प पूर्णिमा को भी जारी रखें। TOVP की गौड़ीय पद्धति में कृष्णनाम-जप, भागवतपाठ, राधाकृष्णपूजा, दीपदान और तुलसीसेवा सुझाई गई हैं। पूर्णिमा सहित किसी शुभदिन 33 दीपों का सुझाव भी है; यह उस परम्परा का निर्देश है। आहार-विधान सामर्थ्य के अनुसार चुनने को कहा गया है। अलग अनिवार्य अधिक-पूर्णिमा निर्जल उपवास, जागरण या निश्चित पारणा-समय यहाँ सत्यापित नहीं है।","tel":"పురుషోత్తమమాస వ్రతం తీసుకున్నవారు పౌర్ణమినాడు కూడా తమ మాససంకల్పం కొనసాగించాలి. మాయాపూర్ TOVP మార్గదర్శకంలో కృష్ణనామజపం, భాగవతపఠనం, రాధాకృష్ణపూజ, దీపం, తులసీసేవ సూచించబడ్డాయి. పౌర్ణమితో సహా మాసంలోని శుభదినాన 33 దీపాలు సమర్పించే సూచన కూడా ఉంది; ఇది ఆ సంప్రదాయ సూచన. ఆహారనియమాన్ని తమ సామర్థ్యానికి తగినట్లు ఎంచుకోమని అదే మూలం చెబుతుంది. ప్రత్యేక పౌర్ణమి నిర్జల ఉపవాసం, తప్పనిసరి జాగరణ లేదా ఖచ్చిత పారాణ సమయం నిర్ధారణ కాలేదు."},"differs":true}];

  /* ---------- the Satyanārāyaṇa vratakathā ----------
     Not one month's story but the katha read on any pūrṇimā a
     household keeps. Five chapters, with the keeping drawn from the
     circulated text's own procedural verses. */
  const satya = {"name":{"roman":"Satyanārāyaṇa Vrata Kathā","deva":"सत्यनारायण व्रतकथा","tel":"సత్యనారాయణ వ్రతకథ"},"source":{"roman":"Skanda Purāṇa, Revā-khaṇḍa — the circulated five chapters","deva":"स्कन्द पुराण, रेवा-खण्ड — प्रचलित पाँच अध्याय","tel":"స్కాంద పురాణం, రేవాఖండం — ప్రచారంలోని ఐదు అధ్యాయాలు"},"lead":{"roman":"Read on any Pūrṇimā a household chooses, and on Saṅkrānti; the text permits a suitable day.","deva":"परिवार द्वारा चुनी किसी भी पूर्णिमा और संक्रान्ति को पढ़ी जाती है; पाठ किसी भी उपयुक्त दिन की अनुमति देता है।","tel":"కుటుంబం ఎంచుకున్న ఏ పౌర్ణమి నాడైనా, సంక్రాంతి నాడైనా చదువుతారు; అనుకూలమైన ఏ రోజైనా చదవవచ్చని పాఠం చెబుతుంది."},"niyama":{"roman":"These cited procedural verses do not prescribe a compulsory waterless fast. They explicitly include receiving prasada and feeding others. A separate family fasting practice must be labelled as that practice, rather than derived from this passage.","deva":"उद्धृत विधिश्लोक अनिवार्य निर्जल उपवास नहीं कहते। परिवार का अलग उपवासाचार हो तो उसे परिवाराचार के रूप में ही पहचानें।","tel":"ఇక్కడ సూచించిన విధిశ్లోకాలు తప్పనిసరి నిర్జల ఉపవాసాన్ని చెప్పవు. కుటుంబంలో ప్రత్యేక ఉపవాసాచారం ఉంటే దానిని కుటుంబాచారంగానే గుర్తించాలి."},"chapters":[{"num":1,"title":{"roman":"The sages' question and Vishnu's teaching to Narada","deva":"ऋषियों का प्रश्न और नारद को विष्णु का उपदेश","tel":"నైమిశారణ్యంలో ప్రశ్న — నారదునికి విష్ణువు ఉపదేశం"},"body":{"roman":"In Naimisharanya, Shaunaka and the other sages asked Suta which vow or austerity could fulfil people's aspirations. Suta introduced the teaching Vishnu had given Narada. Travelling through the worlds, Narada saw people on earth suffering through their own actions. Concerned for them, he went to Vishnu's abode, praised the Lord and asked for a simple way to relieve their distress. Vishnu commended Narada's concern and taught the Satyanarayana vow. Devotees should worship with faith, gather relatives and Brahmins, hear the story, offer food and receive prasada. The text mentions bananas, ghee, milk, wheat flour and sugar or jaggery. Worship may be performed on any day, at the beginning of evening. Suta then related accounts of people who had observed the vow.","deva":"नैमिषारण्य में शौनक आदि ऋषियों ने सूत से पूछा, “किस व्रत या तप से मनुष्यों को अभीष्ट फल मिलता है? कृपया विस्तार से बताइए।” सूत ने कहा कि नारद के पूछने पर विष्णु ने जो बताया था, वही वे सुनाएँगे। लोकों में घूमते हुए नारद ने पृथ्वी पर लोगों को अपने कर्मों के कारण अनेक दुःख भोगते देखा। उनके लिए सरल उपाय जानने हेतु वे विष्णुलोक गए, भगवान की स्तुति की और दुःखनिवृत्ति का मार्ग पूछा। विष्णु ने उनकी लोकहित की भावना सराहकर सत्यनारायण व्रत बताया। श्रद्धापूर्वक पूजा, परिजनों और ब्राह्मणों के साथ कथाश्रवण, नैवेद्य और प्रसाद ग्रहण करने का उपदेश दिया। पाठ में केले, घी, दूध, गेहूँ के आटे और चीनी या गुड़ का उल्लेख है। किसी भी दिन सायंकाल के आरम्भ में पूजा की जा सकती है। फिर सूत ने व्रत करने वालों के वृत्तान्त सुनाए।","tel":"నైమిశారణ్యంలో శౌనకుడు మొదలైన మునులు సూతుణ్ని అడిగారు: “ఏ వ్రతం, ఏ తపస్సు వల్ల మనుష్యులకు కోరిన ఫలం లభిస్తుంది? దయచేసి వివరించండి.” సూతుడు, “ఇదే విషయాన్ని నారదుడు అడిగినప్పుడు విష్ణువు చెప్పిన ఉపదేశాన్ని వినండి” అన్నాడు. నారదుడు లోకాలలో సంచరిస్తూ భూమిపై ప్రజలు తమ కర్మల వల్ల ఎన్నో బాధలు పడుతున్నారని చూశాడు. వారి దుఃఖాన్ని తగ్గించే సులభమార్గం తెలుసుకోవడానికి విష్ణులోకానికి వెళ్లి భగవంతుణ్ని స్తుతించాడు. “ప్రభూ! మానవుల బాధలు ఎలా తొలగుతాయి?” అని ప్రార్థించాడు. విష్ణువు అతని లోకహితకాంక్షను మెచ్చుకుని సత్యనారాయణ వ్రతాన్ని ఉపదేశించాడు. భక్తిశ్రద్ధలతో, బంధువులు, బ్రాహ్మణులతో కలిసి పూజ చేసి, కథను విని, నైవేద్యం సమర్పించి, ప్రసాదాన్ని స్వీకరించాలని చెప్పాడు. అరటిపండ్లు, నెయ్యి, పాలు, గోధుమపిండి, చక్కెర లేదా బెల్లం వంటి పదార్థాలను పాఠం పేర్కొంటుంది. వ్రతం ఏ రోజైనా ఆచరించవచ్చని, సాయంత్రారంభంలో పూజ చేయవచ్చని చెబుతుంది. తరువాత సూతుడు వ్రతాన్ని ఆచరించినవారి కథలు చెప్పాడు."}},{"num":2,"title":{"roman":"The poor Brahmin and the wood-seller","deva":"काशी का निर्धन ब्राह्मण और लकड़ियाँ बेचने वाला","tel":"కాశీలోని పేద బ్రాహ్మణుడు — కట్టెలమ్మేవాడు"},"body":{"roman":"A poor Brahmin in Kashi wandered hungry and thirsty, seeking alms. Vishnu approached as an elderly Brahmin, asked about his distress, taught him the vow and disappeared. Thinking about the instruction, the man could not sleep. Next morning he resolved to perform the worship and went begging. He received plentiful resources that day and used them to observe the vow with his relatives. The story says his distress ended, prosperity followed, and monthly observance eventually brought liberation. During one such worship, a wood-seller asked about the vow, drank water and received prasada. He resolved to perform it using that day's earnings. His wood sold for twice the usual price. He purchased offerings, gathered his relatives and worshipped. Suta says that wealth, children and, eventually, the Lord's abode followed.","deva":"काशी में एक निर्धन ब्राह्मण भूख-प्यास से पीड़ित होकर भिक्षा के लिए भटकता था। विष्णु वृद्ध ब्राह्मण बनकर आए, उसका दुःख पूछा, व्रत की विधि बताई और अदृश्य हो गए। उपदेश का विचार करते हुए वह रात में सो नहीं सका। सुबह व्रत का संकल्प करके भिक्षा के लिए निकला। उस दिन पर्याप्त धन मिला। उससे परिजनों के साथ पूजा की। कथा के अनुसार उसका दुःख मिटा और समृद्धि आई। वह हर महीने व्रत करता रहा और अंत में मोक्ष पाया। एक बार पूजा के समय लकड़ियाँ बेचने वाला आया। उसने व्रत के बारे में जाना, पानी पिया और प्रसाद लिया। उसने उस दिन की कमाई से पूजा करने का संकल्प किया। लकड़ियों का दाम दुगुना मिला। सामग्री लेकर उसने परिजनों को बुलाया और पूजा की। सूत कहते हैं कि उसे धन, संतान और अंत में भगवान का लोक मिला।","tel":"కాశీలో ఒక పేద బ్రాహ్మణుడు ఆకలి, దాహాలతో భిక్ష కోసం తిరిగేవాడు. అతని బాధను చూసిన విష్ణువు వృద్ధ బ్రాహ్మణుడి రూపంలో వచ్చి కారణం అడిగాడు. తన దారిద్ర్యాన్ని చెప్పిన అతనికి సత్యనారాయణ వ్రతవిధిని వివరించి అదృశ్యమయ్యాడు. ఆ ఉపదేశాన్ని తలచుకుంటూ బ్రాహ్మణుడు రాత్రంతా నిద్రపోలేదు. మరుసటి ఉదయం వ్రతం చేయాలని సంకల్పించి భిక్షకు వెళ్లాడు. ఆ రోజు ఎక్కువ ధనం లభించింది. దానితో బంధువులతో కలిసి పూజ చేశాడు. కథ ప్రకారం దుఃఖం తొలగి సంపద కలిగింది; ప్రతి నెలా వ్రతం కొనసాగించి చివరకు మోక్షం పొందాడు. ఒకసారి పూజ జరుగుతుండగా కట్టెలమ్మేవాడు వచ్చాడు. వ్రతం గురించి అడిగి, నీరు తాగి, ప్రసాదం తీసుకున్నాడు. ఆ రోజు కట్టెల అమ్మకంతో వచ్చిన ధనంతో తానూ వ్రతం చేస్తానని సంకల్పించాడు. కట్టెలకు రెట్టింపు ధర లభించింది. పూజాసామగ్రి కొనుక్కొని ఇంటికి వెళ్లి బంధువులను పిలిచి వ్రతం చేశాడు. అతనికి సంపద, సంతానం, చివరకు సత్యదేవుని లోకం లభించాయని సూతుడు చెప్పాడు."}},{"num":3,"title":{"roman":"Sadhu's promise, his family and King Chandraketu","deva":"साधु का वचन, लीलावती, कलावती और चन्द्रकेतु","tel":"సాధువు వాగ్దానం — లీలావతి, కళావతి, చంద్రకేతు"},"body":{"roman":"King Ulkamukha worshipped Satyanarayana with his wife beside the Bhadrashila river. A merchant named Sadhu asked him about the observance. Having learned its significance, Sadhu told his wife Lilavati that he would perform it when they had a child. Their daughter Kalavati was born. When reminded, he postponed the vow until her marriage, and then forgot it again. Later, Sadhu and his son-in-law traded in King Chandraketu's territory. A thief fleeing the king's guards abandoned stolen royal wealth beside them. Without investigation, they were imprisoned and their property confiscated. Theft at home also left Lilavati and Kalavati destitute. Kalavati encountered the worship in a Brahmin's house, heard the story and received prasada. On learning this, Lilavati performed the vow and prayed for her family. The Lord appeared to Chandraketu in a dream, directing him to free the prisoners. The king honoured them and returned twice the confiscated wealth.","deva":"राजा उल्कामुख पत्नी सहित भद्रशीला नदी के किनारे सत्यनारायण की पूजा करते थे। साधु नामक व्यापारी ने व्रत के बारे में पूछा। घर लौटकर उसने पत्नी लीलावती से कहा कि संतान होने पर व्रत करेगा। बेटी कलावती जन्मी। पत्नी के याद दिलाने पर उसने विवाह के समय पूजा करने को कहा, लेकिन विवाह में भी व्रत भूल गया। बाद में वह दामाद के साथ राजा चन्द्रकेतु के क्षेत्र में व्यापार करने गया। राजधन चुराकर भागते चोर ने पीछा करते सैनिकों को देखकर धन उनके पास छोड़ दिया। बिना जाँच दोनों बन्दी बनाए गए और उनकी सम्पत्ति ले ली गई। घर में भी चोरी होने से लीलावती और कलावती निर्धन हो गईं। कलावती ने एक ब्राह्मण के घर पूजा देखकर कथा सुनी और प्रसाद लिया। उससे जानकर लीलावती ने व्रत किया और परिवार की रक्षा माँगी। भगवान ने चन्द्रकेतु को स्वप्न में बन्दियों को छोड़ने का आदेश दिया। राजा ने उनका आदर किया और लिया हुआ धन दुगुना करके लौटाया।","tel":"ఉల్కాముఖుడు అనే రాజు భార్యతో కలిసి భద్రశీలా నదీతీరంలో సత్యనారాయణ వ్రతం చేసేవాడు. సాధువు అనే వ్యాపారి అక్కడికి వచ్చి ఆరాధన గురించి అడిగాడు. రాజు వ్రతమహిమను వివరించాడు. సంతానం లేని సాధువు ఇంటికి వెళ్లి భార్య లీలావతితో, “మనకు సంతానం కలిగితే ఈ వ్రతం చేస్తాను” అన్నాడు. వారికి కళావతి అనే కుమార్తె జన్మించింది. లీలావతి గుర్తుచేసినప్పుడు, కుమార్తె వివాహసమయంలో చేస్తానన్నాడు. వివాహం జరిగినప్పుడు కూడా వ్రతం మరచిపోయాడు. తరువాత అల్లుడితో వ్యాపారానికి చంద్రకేతు రాజు పాలించే ప్రాంతానికి వెళ్లాడు. రాజధనం దొంగిలించిన దొంగ, వెంబడించే భటాలను చూసి వారి దగ్గర దాన్ని వదిలి పారిపోయాడు. విచారణ లేకుండా సాధువు, అల్లుడు చెరసాలలో పెట్టబడ్డారు; వారి సంపద తీసుకోబడింది. ఇంట్లోనూ చోరీ జరిగి లీలావతి, కళావతి దారిద్ర్యంలో పడ్డారు. ఒకరోజు కళావతి బ్రాహ్మణుని ఇంట్లో వ్రతకథ విని ప్రసాదం తీసుకుంది. ఆమె చెప్పగా లీలావతి వ్రతం చేసి కుటుంబాన్ని కాపాడమని ప్రార్థించింది. భగవంతుడు చంద్రకేతుకు స్వప్నంలో బందీలను విడుదల చేయమన్నాడు. రాజు వారిని ఆదరించి, తీసుకున్న ధనానికి రెట్టింపు ఇచ్చి పంపించాడు."}},{"num":4,"title":{"roman":"The cargo and Kalavati's forgotten prasada","deva":"नाव का धन और कलावती का छूटा प्रसाद","tel":"నావలోని సంపద — కళావతి మరచిన ప్రసాదం"},"body":{"roman":"On Sadhu's journey home, Satyanarayana appeared as a staff-bearing ascetic and asked what his boat contained. Sadhu dismissively said it held only creepers and leaves. “Let your words become true,” replied the Lord. The valuable cargo changed into those things. Distressed, Sadhu followed his son-in-law's advice, returned to the ascetic and sought forgiveness. He praised the Lord and promised worship according to his means. The cargo was restored. He worshipped and continued home. Hearing of their arrival, Lilavati completed her worship and went to greet them. Kalavati also completed worship, but hurried away without receiving prasada. Her husband and the boat vanished into the water. She lamented and considered following him, holding his sandals. Sadhu and the family prayed. A heavenly voice explained that Kalavati had left the prasada and should return home, receive it and come back. When she did so, her husband reappeared. The family returned safely. Sadhu thereafter worshipped on full moons and Sankrantis and eventually reached the Lord's abode.","deva":"लौटते समय सत्यनारायण दण्डधारी संन्यासी बनकर आए और नाव में रखी वस्तुएँ पूछीं। साधु ने उपेक्षा से कहा, “इसमें लताएँ और पत्ते हैं।” भगवान ने कहा, “तुम्हारा कथन सच हो जाए।” नाव की सम्पत्ति सचमुच लताओं और पत्तों में बदल गई। दुखी व्यापारी दामाद की सलाह पर संन्यासी के पास गया और क्षमा माँगी। भगवान की स्तुति करके सामर्थ्य के अनुसार पूजा का वचन दिया। धन वापस मिला। पूजा करके उसने यात्रा जारी रखी। उनके आने की खबर सुनकर लीलावती पूजा पूरी करके मिलने गई। कलावती भी पूजा समाप्त कर गई, पर प्रसाद लेना भूल गई। उसका पति और नाव जल में अदृश्य हो गए। वह रोई और पति की पादुकाएँ लेकर उसके पीछे जाने का विचार करने लगी। परिवार ने प्रार्थना की। आकाशवाणी ने बताया कि कलावती प्रसाद छोड़कर आई है; घर लौटकर उसे ग्रहण करे। उसने ऐसा किया तो पति फिर दिखाई दिया। परिवार सुरक्षित घर लौटा। साधु ने बाद में पूर्णिमा और संक्रान्ति को पूजा जारी रखी और अंत में भगवान का लोक पाया।","tel":"సాధువు తిరుగు ప్రయాణంలో ఉండగా సత్యనారాయణుడు దండధారి సన్యాసి రూపంలో వచ్చి నావలో ఏముందో అడిగాడు. సాధువు నిర్లక్ష్యంగా, “లతలు, ఆకులే ఉన్నాయి” అన్నాడు. “నీ మాట నిజమవుగాక” అని భగవంతుడు వెళ్లిపోయాడు. నావలోని సంపద నిజంగానే లతలు, ఆకులుగా మారింది. సాధువు దుఃఖించాడు. అల్లుడి సూచనతో సన్యాసి దగ్గరకు వెళ్లి క్షమాపణ కోరాడు. భగవంతుణ్ని స్తుతించి, శక్తిమేరకు పూజ చేస్తానని అన్నాడు. అనుగ్రహంతో సంపద తిరిగి వచ్చింది. పూజ చేసి ప్రయాణం కొనసాగించాడు. వారి రాకవార్త విన్న లీలావతి పూజ ముగించి భర్తను కలవడానికి వెళ్లింది. కళావతి కూడా పూజ ముగించినా ప్రసాదం తీసుకోకుండా తొందరగా వెళ్లింది. ఆమె భర్త, నావ నీటిలో అదృశ్యమయ్యారు. ఆమె తీవ్రంగా విలపించింది; భర్త పాదుకలు పట్టుకుని అతనిని అనుసరించాలని అనుకుంది. సాధువు కుటుంబంతో ప్రార్థించాడు. కళావతి ప్రసాదాన్ని విడిచి వచ్చిందని, ఇంటికి వెళ్లి స్వీకరించి తిరిగిరావాలని ఆకాశవాణి చెప్పింది. ఆమె అలా చేయగానే భర్త కనిపించాడు. కుటుంబం క్షేమంగా ఇంటికి చేరింది. సాధువు తరువాత పౌర్ణమి, సంక్రాంతి రోజుల్లో పూజ కొనసాగించి సత్యదేవుని లోకం చేరాడు."}},{"num":5,"title":{"roman":"King Tungadhvaja and the cowherds","deva":"तुङ्गध्वज और गोपालों की पूजा","tel":"తుంగధ్వజుడు — గోపాలుల పూజ"},"body":{"roman":"Tungadhvaja was a king devoted to governing his subjects. Returning from a hunt, he saw cowherds happily worshipping Satyanarayana with their relatives beneath a banyan tree. Proudly, he neither joined them nor bowed. They placed prasada near him, but he left it behind. The narrative then describes the loss of his hundred sons and his wealth. Reflecting on his disrespect, he returned to the cowherds and worshipped with them in humility and faith. His sons and prosperity were restored. After a happy life, he reached the Lord's abode. Suta concluded the teaching to the sages. Truthfulness, keeping promises, humility, devotion and reverence for prasada recur throughout these accounts. The described benefits are the religious narrative's statements of merit.","deva":"तुङ्गध्वज प्रजापालन में लगे रहने वाले राजा थे। शिकार से लौटते हुए उन्होंने बरगद के नीचे गोपालों को परिजनों सहित आनंद से सत्यनारायण की पूजा करते देखा। अभिमान के कारण वे न उनके पास गए, न प्रणाम किया। गोपालों ने उनके पास प्रसाद रखा, पर वे उसे छोड़कर चले गए। कथा में इसके बाद उनके सौ पुत्रों और सम्पत्ति के नष्ट होने का वर्णन है। अपने अनादर का विचार करके राजा वापस गोपालों के पास गए। उनके साथ विनम्रता और श्रद्धा से पूजा की। भगवान की कृपा से पुत्र और सम्पत्ति फिर मिले। सुखपूर्वक जीवन बिताकर वे अंत में सत्यदेव के लोक पहुँचे। सूत ने ऋषियों को इसी प्रकार व्रत का माहात्म्य सुनाया। सत्य, वचनपालन, विनम्रता, भक्ति और प्रसाद का सम्मान इन कथाओं में बार-बार आते हैं। सुख, सम्पत्ति और मुक्ति के वर्णन धार्मिक कथा की फलश्रुति हैं।","tel":"తుంగధ్వజుడు ప్రజాపాలనలో నిమగ్నమైన రాజు. ఒకసారి వేట తరువాత మర్రిచెట్టు దగ్గరకు వచ్చాడు. అక్కడ గోపాలులు తమ బంధువులతో కలిసి ఆనందంగా సత్యనారాయణుని పూజిస్తున్నారు. రాజు గర్వంతో వారి దగ్గరకు వెళ్లలేదు; నమస్కరించలేదు. వారు అతని దగ్గర ప్రసాదం ఉంచినా స్వీకరించకుండా వెళ్లిపోయాడు. తరువాత అతని వందమంది కుమారులు, సంపద నష్టపోయారని కథ చెబుతుంది. పూజను, ప్రసాదాన్ని అవమానించిన తన ప్రవర్తనను తలచుకుని రాజు తిరిగి గోపాలుల దగ్గరకు వెళ్లాడు. వారితో కలిసి భక్తిశ్రద్ధలతో సత్యనారాయణుని పూజించాడు. దైవానుగ్రహంతో సంతానం, సంపద తిరిగి లభించాయి. ఇహలోకంలో సుఖంగా జీవించి చివరకు సత్యదేవుని లోకం చేరాడు. సూతుడు మునులకు ఈ విధంగా వ్రతమహిమను ముగించాడు. సత్యం, ఇచ్చిన మాట నిలబెట్టుకోవడం, వినయం, భక్తి, ప్రసాదగౌరవం ఈ ఐదు కథల్లో పదేపదే కనిపిస్తాయి. దుఃఖనివృత్తి, సంపద, విముక్తి వంటి ఫలాలను మూలకథలోని ఫలశ్రుతిగా చదవాలి."}}]};

  /* ---------- which vrata page shows which pūrṇimā ----------
     The roster names some full moons by their festival, not their
     month; this maps those entries to the month's pūrṇimā story. */
  const BYVRATA = {"hanuman-jayanti":"chaitra-purnima","guru-purnima":"ashadha-purnima","hayagriva-jayanti":"shravana-purnima","upakarma":"shravana-purnima","kartika-purnima":"kartika-purnima","dattatreya-jayanti":"margashirsha-purnima","lalita-jayanti":"magha-purnima","sharad-purnima":"ashvina-purnima","holi":"phalguna-purnima","caitra-purnima":"chaitra-purnima","buddha-purnima":"vaisakha-purnima","snana-yatra":"jyeshtha-purnima","valmiki-jayanti":"ashvina-purnima","kartika-dipa-damodara":"kartika-purnima","annapurna-jayanti":"margashirsha-purnima","shakambhari-purnima":"pausha-purnima","lakshmi-jayanti":"phalguna-purnima","kurma-jayanti":"vaisakha-purnima","annamacharya-jayanti":"vaisakha-purnima","caitanya-jayanti":"phalguna-purnima"};

  /* ---------- selection ----------
     Which of the thirteen a given date is: the engine gives the lunar
     month and whether it is intercalary; the full moon settles the
     rest, since every pūrṇimā is the śukla fifteenth. */
  function pickFor(masaIdx, adhika) {
    if (adhika) return LIST.find((e) => e.key.adhika) || null;
    return LIST.find((e) => e.key.masa === masaIdx) || null;
  }
  function pick(date) {
    const Pa = P(); if (!Pa) return null;
    const loc = Pa.locations.find((l) => l.id === "ujjain") || Pa.locations[0];
    const pa = Pa.forDay(date, loc);
    if (pa == null || pa.masaIdx == null) return null;
    return pickFor(pa.masaIdx, !!pa.masaAdhika);
  }

  const byIdMap = {};
  LIST.forEach((e) => { if (e.id) byIdMap[e.id] = e; });
  function byId(id) { return byIdMap[id] || null; }
  /* the pūrṇimā a roster entry speaks to, whether by its own id or by
     the festival it is listed under */
  function forVrata(id) { return byId(id) || (BYVRATA[id] ? byId(BYVRATA[id]) : null); }
  function hasVrata(id) { return id === "satyanarayana" || !!forVrata(id); }

  return { LIST, satya, pick, pickFor, byId, forVrata, hasVrata, BYVRATA, MASA };
})();
